51	// regionalModeSubsystems is THE manifest of the background units regional mode
52	// runs, in Serve() start order (COR-832): rate-limit cleanup, the globaldb
53	// region check, the provisioning reconciler, then the mirror-done /
54	// perms-backfill / verified-email consumers when NATS built them (NATS is
55	// required at boot in regional mode, so in practice all three are present),
56	// the org-invitation token sweep, the detach cleanup relay, and the
57	// cascade-delete finisher.
58	//
59	// The reconciler is unconditional here: regional always wires a full
60	// JurisdictionCapabilities group (buildJurisdictionCaps in api_server.go), so
61	// provisioningReconcilerSubsystem's nil-caps guard never trips in practice.
62	// RunReconciler's own point-of-use check (the unwired-RepoBridge case)
63	// preserves the warn-and-skip behavior if the bridge is ever unconfigured.
64	//
65	// Regional deliberately does NOT run the perms webhook / read-model consumers:
66	// the GitHub-perms ingress is global-only (regional builds neither consumer).
67	// The account-erasure poller is started inline in Serve() (it needs the
68	// fully-wired *api.Server as its region eraser), not via this manifest.
69	func regionalModeSubsystems(deps serveDeps, srv *coreapi.Server) ([]subsystem, error) {
70		var (
71			subs []subsystem
72			err  error
73		)
74		if subs, err = requireSubsystem(subs, srv, rateLimitCleanupSubsystem); err != nil {
75			return nil, err
76		}
77		// The check belongs on the GLOBAL pool — the multi-region database with the
78		// REGIONAL BY ROW tables — never on this cell's regional pool.
79		if subs, err = requireSubsystem(subs, deps.globalPool, globalDBRegionCheckSubsystem); err != nil {
80			return nil, err
81		}
82		if subs, err = requireSubsystem(subs, srv.JurisdictionCaps(), provisioningReconcilerSubsystem); err != nil {
83			return nil, err
84		}
85		if subs, err = maybeSubsystem(subs, deps.mirrorCreateConsumer, mirrorCreateSubsystem); err != nil {
86			return nil, err
87		}
88		for _, c := range deps.mirrorDoneConsumers {
89			if subs, err = requireSubsystem(subs, c, mirrorDoneSubsystem); err != nil {
90				return nil, err
91			}
92		}
93		if subs, err = maybeSubsystem(subs, deps.nativeMirrorExecutor, nativeMirrorExecutorSubsystem); err != nil {
94			return nil, err
95		}
96		if subs, err = maybeSubsystem(subs, deps.nativeMirrorCreateConsumer, nativeMirrorCreateSubsystem); err != nil {
97			return nil, err
98		}
99		if subs, err = maybeSubsystem(subs, deps.nativeMirrorRequestSweep, nativeMirrorRequestSweepSubsystem); err != nil {
100			return nil, err
101		}
102		if subs, err = maybeSubsystem(subs, deps.entireDataPrimarySink.assignmentPass(), entireDataPrimaryPassSubsystem); err != nil {
103			return nil, err
104		}
105		if subs, err = maybeSubsystem(subs, deps.trustReconciler, trustReconcilerSubsystem); err != nil {
106			return nil, err
107		}
108		if subs, err = maybeSubsystem(subs, deps.placementAcceptanceWorker, placementAcceptanceSubsystem); err != nil {
109			return nil, err
110		}
111		if subs, err = maybeSubsystem(subs, deps.trustRootOnCreateSweep, trustRootOnCreateSubsystem); err != nil {
112			return nil, err
113		}
114		if subs, err = maybeSubsystem(subs, deps.mirrorURLDrainer, mirrorURLDrainerSubsystem); err != nil {
115			return nil, err
116		}
117		if subs, err = maybeSubsystem(subs, deps.repoCellCleanupDrainer, repoCellCleanupDrainerSubsystem); err != nil {
118			return nil, err
119		}
120		if subs, err = maybeSubsystem(subs, deps.permsBackfillConsumer, permsBackfillSubsystem); err != nil {
121			return nil, err
122		}
123		if subs, err = maybeSubsystem(subs, deps.pluginGrantsConsumer, pluginGrantsSubsystem); err != nil {
124			return nil, err
125		}
126		if subs, err = maybeSubsystem(subs, deps.verifiedEmailConsumer, verifiedEmailSubsystem); err != nil {
127			return nil, err
128		}
129		if subs, err = maybeSubsystem(subs, deps.emailRelay, emailRelaySubsystem); err != nil {
130			return nil, err
131		}
132		if subs, err = maybeSubsystem(subs, deps.emailConsumer, emailConsumerSubsystem); err != nil {
133			return nil, err
134		}
135		if subs, err = requireSubsystem(subs, deps.orgInvitationTokenSweeper, orgInvitationTokenSweepSubsystem); err != nil {
136			return nil, err
137		}
138		if subs, err = requireSubsystem(subs, srv, detachCleanupRelaySubsystem); err != nil {
139			return nil, err
140		}
141		if subs, err = requireSubsystem(subs, srv, repoDetachSweepSubsystem); err != nil {
142			return nil, err
143		}
144		if subs, err = requireSubsystem(subs, srv, cascadeDeleteFinisherSubsystem); err != nil {
145			return nil, err
146		}
147		return subs, nil
148	}
