150	// buildRegionalServeDeps assembles the full serving-core dependency graph for a
151	// regional core: identity/regional/authz/resource stores, the account-erasure
152	// outbox (drained by a per-region poller, ADR 20260708) and the transactional-
153	// email fan-out (outbox + relay + consumer), signing keys, JWKS,
154	// the cluster registry (reconciled here — serving cores own it), and the repo
155	// bridge. The account-deletion reaper does NOT use this bootstrap: it wires a
156	// lean control-plane-only graph via buildReaperDeps (ADR 20260707), which is why
157	// this no longer takes withFanout / reconcileRegistry flags.
158	func buildRegionalServeDeps(ctx context.Context, cfg Config, lifecycleEmitter *resourceevents.Emitter, billingSubjects []runnerpolicy.BillingSubject) (serveDeps, func(), error) {
159		var deps serveDeps
160	
161		if cfg.GlobalCockroachDSN == "" {
162			return deps, func() {}, errors.New("GLOBAL_COCKROACH_DSN is required in regional mode")
163		}
164		if cfg.Jurisdiction == "" {
165			return deps, func() {}, errors.New("--jurisdiction is required in regional mode")
166		}
167		if cfg.AuthBaseURL == "" {
168			return deps, func() {}, errors.New("ENTIRE_CORE_AUTH_BASE_URL is required in regional mode")
169		}
170		billingEnforcement, err := runnerpolicy.ParseBillingEnforcement(cfg.RunnerBillingEnforcement)
171		if err != nil {
172			return deps, func() {}, fmt.Errorf("ENTIRE_RUNNER_BILLING_ENFORCEMENT: %w", err)
173		}
174		if cfg.RegionHosts == "" {
175			return deps, func() {}, errors.New("REGION_HOSTS is required in regional mode")
176		}
177	
178		// Two pools: global (identity, resources, keys) + regional (PII, audit).
179		globalPool, err := postgres.NewPool(ctx, cfg.GlobalCockroachDSN, postgres.WithMaxConns(pgPoolMaxConns))
180		if err != nil {
181			return deps, func() {}, fmt.Errorf("connect global cockroachdb: %w", err)
182		}
183	
184		regionalPool, err := postgres.NewPool(ctx, cfg.CockroachDSN, postgres.WithMaxConns(pgPoolMaxConns))
185		if err != nil {
186			globalPool.Close()
187			return deps, func() {}, fmt.Errorf("connect regional cockroachdb: %w", err)
188		}
189		cleanups := []func(){
190			func() { regionalPool.Close() },
191			func() { globalPool.Close() },
192		}
193		cleanup := func() {
194			for _, cleanup := range slices.Backward(cleanups) {
195				cleanup()
196			}
197		}
198	
199		// Reads go to the local SpiceDB (sidecar/replica); writes go to the
200		// read-write authz-writer when configured, else back to the sidecar.
201		spiceRead, spiceWrite, err := dialSpiceDB(cfg)
202		if err != nil {
203			cleanup()
204			return deps, func() {}, err
205		}
206		// Read-mostly: only contacts the authz-writer when the datastore's schema
207		// is stale/absent, so a writer/NLB outage doesn't block boot. Never fatal:
208		// a fresh cell that can't write its schema serves schema-less (authz-gated
209		// requests 500) and the retry converges once the writer is back.
210		if !authz.EnsureSchema(ctx, spiceRead, spiceWrite) {
211			retryCtx, cancelRetry := context.WithCancel(ctx)
212			cleanups = append(cleanups, cancelRetry)
213			go authz.EnsureSchemaUntilCurrent(retryCtx, spiceRead, spiceWrite, time.Minute)
214		}
215	
216		deps.globalPool = globalPool
217		deps.identitySvc = membershipIdentityStore(cfg, globalPool)
218		deps.authzSvc = authz.NewStoreRW(spiceRead, spiceWrite)
219	
220		// System service-account grants are reconciled by `entire-core
221		// bootstrap` (see internal/entirecore/bootstrap.go); they require
222		// the system org and service_accounts rows that bootstrap creates.
223		// Run bootstrap once before the first serve.
224	
225		pluginsStore := plugins.NewStore(globalPool)
226		pluginCatalog := plugins.NewCatalogStore(globalPool)
227		deps.pluginCatalog, deps.pluginAdmin = pluginCatalog, pluginCatalog
228		// Held concrete too: the executor needs PublishRepoInTx, not on the interface.
229		resourceStore := resource.NewStore(globalPool, deps.authzSvc,
230			resource.WithProcessingCellElection(cfg.MirrorElectInProcessingCellEnabled))
231		// The detach runs in the placement's jurisdiction, so only a regional
232		// core serves it.
233		deps.detachStore = repodetach.NewStore(globalPool)
234		deps.resourceSvc = resourceStore
235		deps.automationSvc = automation.NewStore(globalPool)
236		grantProvisioner := plugins.Provisioner{
237			Installations: pluginsStore, Plugins: pluginCatalog, Automations: deps.automationSvc, Grants: deps.authzSvc, Fence: resourceStore,
238		}
239		deps.detachPluginReconciler = plugins.CoveringReconciler{Installations: pluginsStore, Provisioner: grantProvisioner}
240		deps.pluginsSvc = pluginsStore
241		deps.runnerPolicySvc = newRunnerPolicyStore(globalPool, billingEnforcement, billingSubjects)
242		if err := deps.runnerPolicySvc.RegisterModeGauge(); err != nil {
243			slogutil.Warn(ctx, "runner policy mode gauge registration failed", slog.String("error", err.Error()))
244		}
245		billingEnsure := billing.NewGlobalEnsureStore(globalPool)
246		billingDir := newRegionalBillingDirectory(ctx, cfg, deps.resourceSvc, deps.identitySvc)
247		deps.billingEnsurer = billing.NewEnsurer(billingEnsure, billingDir)
248		deps.runnerPolicySvc.WithBillingEnsurer(deps.billingEnsurer)
249		// Built before billing wiring, which sends billing events through it.
250		deps.analyticsClient = analytics.New(cfg.AnalyticsConfig())
251		deps.billingOverviewCache = billing.NewOverviewCache()
252		if err := wireMetronomeWebhooks(cfg, globalPool, billingDir, &deps); err != nil {
253			cleanup()
254			return deps, func() {}, err
255		}
256		if err := wireBillingAccountConsumers(cfg, billingConsumerPools{global: globalPool, regional: regionalPool},
257			billing.NewMetronomeClient(cfg.MetronomeAPIKey), deps.runnerPolicySvc, billingDir, &deps); err != nil {
258			cleanup()
259			return deps, func() {}, err
260		}
261		if deps.billingSvc != nil {
262			deps.billingTrialPoller = billing.NewTrialPoller(billingEnsure, deps.billingSvc, billingDir, cfg.Jurisdiction)
263		}
264		globalRepoDeletionOutbox := repodeletion.NewNativeMirror(globalPool, cfg.Jurisdiction)
265		regionalRepoDeletionOutbox := repodeletion.NewRegional(regionalPool, cfg.Jurisdiction)
266		deps.repoDeletionRelays = []*repodeletion.Relay{
267			globalRepoDeletionOutbox.Relay(lifecycleEmitter),
268			regionalRepoDeletionOutbox.Relay(lifecycleEmitter),
269		}
270		// The created-side twin (COR-1359): the creation executor enqueues the
271		// fully marshaled native_mirror.created in the same transaction as its
272		// terminal stage CAS; this relay publishes those rows with PubAck. Same
273		// global DB and jurisdiction scoping as the native-mirror deletion outbox.
274		deps.nativeMirrorCreatedRelay = nativemirror.NewCreatedOutboxRelay(globalPool, cfg.Jurisdiction, lifecycleEmitter)
275		// Resource events ride the same global DB as repo_group, which the detach
276		// rewire rewrites in the same transaction as the enqueue. The relay also
277		// samples stalled detaches.
278		deps.resourceEventRelay = outbox.NewRelay(globalPool, cfg.Jurisdiction, lifecycleEmitter,
279			outbox.WithSampler(repodetach.NewStalledSampler(globalPool, cfg.Jurisdiction).Record))
280		// githubPerms reads/writes the global GitHub-perms mirror; bind it
281		// to the global pool.
282		deps.githubPerms = githubperms.NewService(globalPool,
283			githubperms.WithRepoGroupNameRefresher(resource.NewStore(globalPool, nil)),
284			githubperms.WithMirrorURLAliasRefresher(mirrorrepo.NewService(globalPool)),
285		)
286		// mirrorrepo: placement + URL tables in the global pool; the
287		// revoker clears a suspended placement's SpiceDB grants.
288		deps.entireDataPrimarySink = &lazyEntireDataPrimaryReconciler{}
289		deps.mirrorRepoSvc = newMirrorRepoService(globalPool, deps.resourceSvc, deps.entireDataPrimarySink, lifecycleEmitter)
290		deps.nativeMirrorSvc = nativemirror.New(globalPool,
291			nativemirror.WithRepoDeletionOutbox(globalRepoDeletionOutbox),
292			nativemirror.WithRegistryPublisher(resourceStore))
293		// gitJobsPublisher fires the mirror_git_v1 sync_repo on create so
294		// the per-cluster mirror-worker picks up the initial clone
295		// immediately, instead of waiting for the periodic resync.
296		// ENTIRE_NATS_URL is required; boot fails otherwise.
297		gitJobsPub, gitJobsCleanup, err := buildGitJobsPublisher(ctx, cfg)
298		if err != nil {
299			cleanup()
300			return deps, func() {}, fmt.Errorf("build gitjobs publisher: %w", err)
301		}
302		cleanups = append(cleanups, gitJobsCleanup)
303		deps.gitJobsPublisher = gitJobsPub
304		// resyncPublisher fires the synthetic push webhook that triggers a
305		// mirror-pipeline resync (ENT-1172). It targets the CENTRAL
306		// webhooks_github_v1 stream (cfg.NatsURL), where cmd/fanout consumes —
307		// not the in-cell mirror stream gitJobsPublisher uses.
308		resyncPub, resyncCleanup, err := buildResyncPublisher(ctx, cfg)
309		if err != nil {
310			cleanup()
311			return deps, func() {}, fmt.Errorf("build resync publisher: %w", err)
312		}
313		cleanups = append(cleanups, resyncCleanup)
314		deps.resyncPublisher = resyncPub
315		// mirrorDoneConsumers drain sync-completion events (repo_ops_v1 mirror_done
316		// op). The composite writer fans each completion to both status stores —
317		// mirror_repos and native_mirrors (intent-gated; disjoint ULID spaces, at
318		// most one row changes). One binds the local NATS; one more per reuse-core
319		// cell binds that cell's remote NATS.
320		deps.mirrorSyncMarkerSink = &lazySyncMarker{}
321		doneWriter := mirrordone.CompositeStatusWriter{
322			Mirrors:       deps.mirrorRepoSvc,
323			NativeMirrors: deps.nativeMirrorSvc,
324		}
325		markStore := mirrordone.CompositeMarkStore{
326			Mirrors:       deps.mirrorRepoSvc,
327			NativeMirrors: deps.nativeMirrorSvc,
328		}
329		mirrorDoneConsumers, mirrorDoneCleanup, err := buildMirrorDoneConsumers(ctx, cfg, doneWriter, markStore, deps.mirrorSyncMarkerSink, cfg.Jurisdiction)
330		if err != nil {
331			cleanup()
332			return deps, func() {}, fmt.Errorf("build mirror-done consumers: %w", err)
333		}
334		if mirrorDoneCleanup != nil {
335			cleanups = append(cleanups, mirrorDoneCleanup)
336		}
337		deps.mirrorDoneConsumers = mirrorDoneConsumers
338		// perms-backfill: the create path enqueues a collaborator-reconcile job
339		// (publisher) that this same in-region consumer drains OFF the request path,
340		// riding the in-cell repo_ops_v1 (perms_backfill op) the mirror-done consumer
341		// already uses. Scoped to this core's jurisdiction. The periodic reconciler
342		// backstops when NATS is absent, so both degrade safely.
343		permsBackfillPub, permsBackfillPubCleanup, err := buildPermsBackfillPublisher(ctx, cfg)
344		if err != nil {
345			cleanup()
346			return deps, func() {}, fmt.Errorf("build perms-backfill publisher: %w", err)
347		}
348		if permsBackfillPubCleanup != nil {
349			cleanups = append(cleanups, permsBackfillPubCleanup)
350		}
351		deps.permsBackfillPublisher = permsBackfillPub
352		permsBackfillConsumer, permsBackfillConsumerCleanup, err := buildPermsBackfillConsumer(ctx, cfg, mirrorPermsReconcileFunc(&deps), buildGranteeVerifyInline(cfg, &deps), cfg.Jurisdiction)
353		if err != nil {
354			cleanup()
355			return deps, func() {}, fmt.Errorf("build perms-backfill consumer: %w", err)
356		}
357		if permsBackfillConsumerCleanup != nil {
358			cleanups = append(cleanups, permsBackfillConsumerCleanup)
359		}
360		deps.permsBackfillConsumer = permsBackfillConsumer
361		deps.serviceAccountSvc = serviceaccount.NewStore(globalPool)
362		deps.oidcfedSvc = oidcfed.NewStore(globalPool)
363		// Concrete *regional.Store: exposed as the regional.Service interface on
364		// deps, but also handed to buildTransactionalEmail below as the
365		// email.Resolver (ResolveContactEmail / ContactDisplayName live on the
366		// concrete store, not the Service interface).
367		regionalStore := regional.NewStore(regionalPool, deps.identitySvc, deps.authzSvc, deps.resourceSvc, cfg.Jurisdiction,
368			regional.WithRepoDeletionOutbox(regionalRepoDeletionOutbox),
369			regional.WithAutomation(deps.automationSvc))
370		deps.regionalSvc = regionalStore
371		// The sweeper needs the concrete *regional.Store (it implements
372		// regional.OrgInvitationTokenStore); regional.Service does not expose
373		// SweepStaleOrgInvitationTokens.
374		deps.orgInvitationTokenSweeper = regional.NewOrgInvitationTokenSweeper(regionalStore, regional.OrgInvitationTokenSweepConfig{
375			Scopes: invitationScopes{resources: deps.resourceSvc},
376		})
377	
378		// Account-erasure outbox (multi-region, ADR 20260708): the reaper enqueues an
379		// erasure row on teardown; this region's poller (started in serve.go) drains
380		// the global outbox and erases the account in its own region. The outbox lives
381		// in the global pool alongside the identity it accompanies. No NATS.
382		deps.erasureOutbox = accounterasure.NewOutbox(globalPool)
383		deps.erasureLedger = erasureledger.NewStore(globalPool)
384	
385		// regionalSvc (a *regional.Store) satisfies email.Resolver. The
386		// invitation mail reads across the regional invitation row, the two
387		// global stores (org name, inviter identity) and, for an account target,
388		// the invitee's contact email, so its resolver is built here from
389		// regionalStore, deps.resourceSvc and deps.identitySvc.
390		invitationResolver := newInvitationResolver(regionalStore, deps.resourceSvc, deps.identitySvc, regionalStore)
391		emailOutbox, emailRelay, emailConsumer, emailCleanup, err := buildTransactionalEmail(ctx, cfg, globalPool, regionalPool, regionalStore, deps.identitySvc, invitationResolver)
392		if err != nil {
393			cleanup()
394			return deps, func() {}, fmt.Errorf("build transactional-email fan-out: %w", err)
395		}
396		cleanups = append(cleanups, emailCleanup)
397		deps.emailOutbox = emailOutbox
398		deps.emailRelay = emailRelay
399		deps.emailConsumer = emailConsumer
400	
401		// verifiedEmailConsumer drains pre-extracted push commit-author jobs off this
402		// jurisdiction's LOCAL github_push_author_v1 island and writes verified_emails
403		// for commit authors homed in this jurisdiction (COR-661/COR-757). Built after
404		// regionalSvc, which it writes through in-process.
405		//
406		// Gated (COR-674): a cell running the standalone `entire-core
407		// verified-email-consumer` Deployment sets ENTIRE_VERIFIED_EMAIL_CONSUMER_IN_SERVE=false
408		// so serve stops carrying the push firehose -- the two must not both drain
409		// the same durable in one cell. Default true keeps the in-process consumer
410		// everywhere it isn't yet split out.
411		if cfg.VerifiedEmailConsumerInServe {
412			verifiedEmailConsumer, verifiedEmailCleanup, err := buildVerifiedEmailConsumer(ctx, cfg, deps.identitySvc, deps.regionalSvc, lifecycleEmitter, cfg.Jurisdiction, deps.erasureLedger)
413			if err != nil {
414				cleanup()
415				return deps, func() {}, fmt.Errorf("build verified-email consumer: %w", err)
416			}
417			if verifiedEmailCleanup != nil {
418				cleanups = append(cleanups, verifiedEmailCleanup)
419			}
420			deps.verifiedEmailConsumer = verifiedEmailConsumer
421		} else {
422			slogutil.Info(ctx, "verified-email push consumer disabled in serve (ENTIRE_VERIFIED_EMAIL_CONSUMER_IN_SERVE=false); expecting a standalone verified-email-consumer Deployment (COR-674)")
423		}
424	
425		// Cluster registry lives on the global pool. STS uses it to resolve a
426		// CLI-typed data-plane host into a jurisdiction so a mirror lookup can
427		// pin to the right row when the same upstream is mirrored in multiple
428		// regions. Reconcile applies the embedded cluster fixture to the global
429		// table on every boot — every regional core writes the same fixture, so
430		// concurrent boots converge on the same state. Serializable isolation makes
431		// them CORRECT, not failure-free: the loser of a write-write race still
432		// gets SQLSTATE 40001 and has to retry client-side, which Reconcile now
