442		// the table to build the repo bridge. (The reaper reads a serve-reconciled
443		// table via its own lean graph and never reconciles — ADR 20260707.)
444		if err := reconcileClusters(ctx, cfg.ClusterFixtureEnv, deps.clusterStore); err != nil {
