// JurisdictionHost returns the base URL of the named jurisdiction's
// console host (empty if unknown). Used by foreign-jurisdiction-aware
// handlers to compose deep links.
func (s *Server) JurisdictionHost(jurisdiction string) string {
	return s.jurisdictionHosts[jurisdiction]
}

// JurisdictionAuthHost returns the named jurisdiction's core origin — its OIDC
// issuer URL, e.g. "https://us.auth.entire.io" — or empty if unconfigured.
// This is the origin a token from that jurisdiction carries as `iss`, and the
// one the 421 cross-jurisdiction redirect hands clients as `home_core_url`.
//
// Distinct from JurisdictionHost, which is the console (a browser surface).
// Prefer this whenever the value is meant for a client to address.
func (s *Server) JurisdictionAuthHost(jurisdiction string) string {
	return s.jurisdictionAuthHosts[jurisdiction]
}

// LookupRepoLocalOrGlobal exposes the regional → global registry repo
// lookup so coreapi can present unified GET /repos/{id} semantics.
// Returns (*model.Repo, jurisdiction string, isForeign bool, error).
// jurisdiction is the repo's home region — this core's own for a regional
// hit ("" on a jurisdiction-agnostic core), the registry's stamp for a
// foreign row — carried alongside because model.Repo deliberately has no
// jurisdiction field (a row's region is implied by whose store it came
// from). isForeign=true means only ID/Name/ClusterSlug are populated.
func (s *Server) LookupRepoLocalOrGlobal(ctx context.Context, repoID model.RepoID) (*model.Repo, string, bool, error) {
	return s.lookupRepoLocalOrGlobal(ctx, repoID)
}

// JurisdictionRedirect returns a *MirrorOpError carrying the 421 redirect to
// the resource's home core, or nil when the owning jurisdiction is local (or
// this core is jurisdiction-agnostic, i.e. global). Reuses the
// same routing the mirror create path uses so foreign-owned org/project/repo
// mutations 421 to the home core instead of acting on a resource this cell
// doesn't own. ownerJurisdiction is the resource's Region (org/project) or
// the registry Jurisdiction (repo).
func (s *Server) JurisdictionRedirect(ownerJurisdiction string) *MirrorOpError {
	return s.jurisdictionRedirect(ownerJurisdiction)
}

// ResolveCreateClusterSlug picks a destination cluster for repo create.
// Returns (slug, status, error); status is the HTTP status the caller
// should emit on error.
func (s *Server) ResolveCreateClusterSlug(ctx context.Context, requested string) (string, int, error) {
	return s.resolveCreateClusterSlug(ctx, requested)
}

// ResolveCreateCluster picks the destination cluster for a /api/v1 repo
// create by its public host (empty = jurisdiction default) and returns the
// cluster's internal slug (for data-plane routing) plus its public host (for
// the response body). status is the HTTP status to surface on error.
func (s *Server) ResolveCreateCluster(ctx context.Context, requestedHost string) (slug, host string, status int, err error) {
	c, st, err := s.resolveCreateClusterByHost(ctx, requestedHost)
	if err != nil {
		return "", "", st, err
	}
	u, err := url.Parse(c.PublicURL)
	if err != nil {
		return "", "", http.StatusInternalServerError, fmt.Errorf("parse cluster public url: %w", err)
	}
	return c.Slug, u.Host, 0, nil
}

// PlatformID surfaces the platform-resource ULID used for platform-
// scoped authz checks. Constant string; exported for coreapi.
const PlatformID = PlatformResourceID

// ResolveClusterHost maps a CLI-typed data-plane host to the cluster it
// addresses and returns that cluster's internal slug. status is the HTTP
// status to surface on failure (400 unknown/blank host, 503 registry
// unconfigured). Mirror deletes match a placement by this slug rather than
// by jurisdiction: several clusters can share a jurisdiction, so a
// jurisdiction match would treat a sibling cluster as the target.
func (s *Server) ResolveClusterHost(ctx context.Context, host string) (slug string, status int, err error) {
	slug, _, _, status, err = s.resolveClusterHost(ctx, host)
	if err != nil {
		return "", status, err
	}
	return slug, http.StatusOK, nil
}

// ResolveClusterHostJurisdiction maps a CLI-typed data-plane host to
// the jurisdiction serving it. Returns (jurisdiction, status, error)
// where status is the HTTP status to surface on failure.
func (s *Server) ResolveClusterHostJurisdiction(ctx context.Context, host string) (string, int, error) {
	jur, err := s.resolveClusterHostJurisdiction(ctx, host)
	if err != nil {
		if rte, ok := errors.AsType[*repoTokenLookupError](err); ok {
			return "", rte.status, err
		}
		return "", http.StatusInternalServerError, err
	}
	return jur, http.StatusOK, nil
}

// CheckOrgManage checks managePermission on the org for the caller.
func (s *Server) CheckOrgManage(ctx context.Context, claims *authn.Claims, orgID model.OrgID, managePermission string) (bool, error) {
	if claims == nil {
		return false, nil
	}
	subject := "account:" + claims.AccountID.String()
	allowed, err := s.authz.Can(ctx, authz.RetryDeniedFresh, subject, managePermission, "org:"+orgID.String())
	if err != nil {
		return false, fmt.Errorf("authz manage check: %w", err)
	}
	return allowed, nil
}

