// org SSO gate. Guarded: refuses while the org still has non-owner
// members, projects, or teams (cascade is a follow-up — COR-564).
func (s *OrgService) DeleteOrg(ctx context.Context, in *corev1.DeleteOrgInput) (*corev1.DeleteOrgOutput, error) {
	claims := api.ClaimsFromContext(ctx)
	if claims == nil {
		return nil, unauthorized("authentication required")
	}
	orgID, err := model.ParseOrgID(in.OrgID)
	if err != nil {
		return nil, badRequest("invalid org id")
	}
	res := s.Server.Resource()
	if res == nil {
		return nil, unavailable("resource service not configured")
	}
	org, err := res.GetOrg(ctx, orgID)
	if err != nil {
		if errors.Is(err, resource.ErrNotFound) {
			return nil, notFound("org not found")
		}
		slogutil.Error(ctx, "GetOrg failed", slog.Any("error", err))
		return nil, internalErr()
	}
	if allowed, err := s.ManageAuthority.checkOrgManage(ctx, s.Server, claims, orgID); err != nil {
		slogutil.Error(ctx, "CheckOrgManage failed", slog.Any("error", err))
		return nil, authzUnavailable()
	} else if !allowed {
		return nil, forbidden("permission denied")
	}
	// In-cell only: an org homed in another jurisdiction is readable here
	// (shared global store) but must be deleted against its home core, which
	// owns the cascade. No-op in global mode. Gated behind the
	// manage check above so the 421's home_core_url isn't disclosed to callers
	// without manage.
	if oe := s.Server.JurisdictionRedirect(org.Region); oe != nil {
		return nil, mapOpError(oe)
	}
	if ok, reason, err := s.Server.CheckOrgSSO(ctx, claims, orgID); err != nil {
		slogutil.Error(ctx, "CheckOrgSSO failed", slog.Any("error", err))
		return nil, authzUnavailable()
	} else if !ok {
		return nil, forbidden(reason)
	}
	// Refuse users before the dependent pre-checks, which a linked org always
	// fails with advice it cannot follow.
	deleteOrg := res.DeleteOrg
	if s.ManageAuthority == authorityPlatform {
		deleteOrg = res.DeleteOrgAllowLinked
	} else if linked, err := res.IsGitHubLinkedOrg(ctx, orgID); err != nil {
		slogutil.Error(ctx, "IsGitHubLinkedOrg failed", slog.String("org_id", orgID.String()), slog.Any("error", err))
		return nil, internalErr()
	} else if linked {
		return nil, conflict(linkedOrgDeleteMsg)
	}

	// Guard the same dependents the admin path does. The DeleteOrg tx
	// drops owner memberships itself, refuses on projects (ErrHasDependents),
	// and FK-fails on teams; pre-checking here turns every dependent into a
	// clean 409 instead of a 500.
	members, err := res.ListMembers(ctx, orgID)
	if err != nil {
-----
			slogutil.Error(ctx, "CheckOrgSSO failed", slog.Any("error", err))
			return nil, authzUnavailable()
		} else if !ok {
			return nil, forbidden(reason)
		}
	}
	deleted, err := res.DeleteProject(ctx, projectID)
	if err != nil {
		switch {
		case errors.Is(err, resource.ErrNotFound):
			return nil, notFound("project not found")
		case errors.Is(err, resource.ErrHasRepos):
			return nil, conflict("project has repos; delete them first")
		case errors.Is(err, resource.ErrProjectReferenced):
			// Same FK-violation branch also catches a repo that raced past
			// DeleteProject's own FOR UPDATE window — a benign, retryable
			// conflict from the caller's point of view, same as ErrHasRepos,
			// not the internal error a 500 would suggest.
			return nil, conflict("project has repos; delete them first")
		}
		slogutil.Error(ctx, "DeleteProject failed", slog.Any("error", err))
		return nil, internalErr()
	}
	s.Server.DomainAuditLog(ctx, claims.AccountID, "project_deleted", "project", deleted.Project.ID.String(), map[string]any{
		"name":       deleted.Project.Name,
		"owner_type": deleted.Project.OwnerType,
		"owner_id":   deleted.Project.OwnerID.String(),
	})
	s.Server.LifecycleEvents().Publish(ctx, resourceevents.TypeProject, deleted.Project.ID.String(), resourceevents.OpDeleted, claims.AccountID.String())
	// Off the home core the sweeper erases them.
	if s.Server.JurisdictionRedirect(project.Region) == nil {
		eraseScopeInvitations(ctx, s.Server, regional.InvitationScopeProject, projectID.String())
	}
	// Revision only: ListProjects takes its id set from a resource lookup, so a
	// lookup pinned past this delete cannot name the project.
	return &corev1.DeleteProjectOutput{
		Status: http.StatusNoContent,
		CommitToken: signCommitToken(ctx, s.Server, "delete_project",
			committoken.Snapshot{Revision: deleted.Revision.Token()}),
	}, nil
}

// ListOrgProjects returns projects belonging to an org the caller can view.
func (s *ProjectService) ListOrgProjects(ctx context.Context, in *corev1.ListOrgProjectsInput) (*corev1.ListOrgProjectsOutput, error) {
	claims := api.ClaimsFromContext(ctx)
	if claims == nil {
		return nil, unauthorized("authentication required")
	}
	orgID, err := model.ParseOrgID(in.OrgID)
	if err != nil {
		return nil, badRequest("invalid org id")
	}
	res := s.Server.Resource()
	authz := s.Server.Authz()
	if res == nil || authz == nil {
		return nil, unavailable("services not configured")
	}
	var notFoundErr, allowed, getOrgFailed, authzFailed bool
	var org *model.Org
	// A plain errgroup.Group, not errgroup.WithContext. The two checks are
	// independent reads; canceling one when the other errors would make a
	// live dependency's own error look identical to that cancellation.
	// getOrgFailed and authzFailed below must not confuse the two.
	var g errgroup.Group
	g.Go(func() error {
		var err error
		if org, err = res.GetOrg(ctx, orgID); err != nil {
			if errors.Is(err, resource.ErrNotFound) {
				notFoundErr = true
				return nil
			}

