// Repo is the jurisdictional record: the full lifecycle and operational
// metadata for a repo, stored in its home jurisdiction's database. The
// jurisdiction itself isn't a field — every row lives in exactly the
// jurisdiction whose store it was read from; the regional store stamps
// its own jurisdiction onto registry rows at publish time.
type Repo struct {
	ID                RepoID
	Name              string
	State             RepoState
	ProvisionAttempts int
	ProvisionReason   string
	// ClusterSlug names the cluster within the home jurisdiction that hosts
	// this repo. Stamped at create/adopt time from the request's selector
	// (or the jurisdiction's default cluster when the caller didn't pin one)
	// and forwarded to the global registry at that same insert (COR-856).
	// Empty for rows created before the cluster-stamping rollout — backfill
	// covers them.
	ClusterSlug string
	// ObjectFormat is the git object hash format for this repo: "sha1" or
	// "sha256". Chosen at create time and immutable thereafter — Git has no
	// in-place conversion between formats. The data plane reads this back
	// on every hashing/packfile path. String rather than a typed enum so
	// core/model stays free of any data-plane (go-git fork) dependency; the
	// bridge to formatcfg.ObjectFormat lives at the proto/data-plane edge.
	// Empty on rows created before the rollout — InsertRepo writes "sha1"
	// when the caller leaves it empty so the Go and SQL sides stay aligned.
	ObjectFormat string
	// CreatedAt is the row's insert time, the moment the repo came into
	// existence with its birth properties (private, by the absence of a
	// public_viewer tuple). Read back so a writer stamping a birth fact can
	// date it to creation rather than to when it happened to run, which is
	// what keeps a late stamp from outranking a user's own later change under
	// the repo_facts LWW guard.
	CreatedAt time.Time
}

// RepoRegistration is the global registry row — what exists and where it
// lives. Written when a jurisdictional provisioning succeeds; read for
// id → jurisdiction routing and cross-jurisdiction admin listings.
//
// ClusterSlug names the cluster within Jurisdiction that hosts the repo.
// Empty for rows written before the cluster-stamping rollout — the backfill
// covers them. Slug rather than cluster ID because clusters.slug is globally
// unique (migration 009) and is the same identifier embedded in JWT
// audiences (service:entiredb:<slug>).
type RepoRegistration struct {
	ID   RepoID
	Name string

	// OwningProjectID is not written to repo_registry (that table's
	// owning_project_id column is unused — nothing reads it, and publishRepoTx
	// no longer writes it). It's still needed here: publishRepoTx uses it to
	// validate the (forge, project) pairing via validateForgeProjectKind, and
	// in its error messages. The group's own owning_project_id — the real
	// ownership record — is set separately by GetOrCreateRepoGroup before
	// PublishRepo is ever called.
	OwningProjectID ProjectID
	Jurisdiction    string
	ClusterSlug     string

	// RepoGroupID is the repo_group this placement belongs to, already
	// resolved (minted if needed) by the caller via GetOrCreateRepoGroup
	// before calling PublishRepo — group resolution and placement
	// registration are two separate calls, not one atomic write. A native
	// repo resolves its own singleton entire-forge group as its own
	// processing primary; a mirror resolves its upstream's shared
	// github-forge group; a native-mirror replica resolves its data
	// primary's existing group. PublishRepo itself never mints — it only
	// attaches the placement to whichever group this names.
	RepoGroupID RepoGroupID
}

