package audit
import (
	"context"
	"encoding/json"
	"fmt"
	"strings"
	"time"
	"entire.io/core/model"
	"github.com/jackc/pgx/v5/pgxpool"
)
// DomainAudit records control-plane events in the global CockroachDB.
// Login/profile/PII events stay in regional via regional.LogAuditEvent.
//
// Reads always hit the global domain_audit_events table. Writes go there
// directly too, unless an outbox pool is configured (regional mode): then Log
// stages the row in the regional domain_audit_outbox — a local-DB durable
// write instead of a synchronous cross-region INSERT — and a Relay drains it
// into the global table (COR-915). Outboxed events become visible to the read
// paths only after the drain, normally within a few seconds.
type DomainAudit struct {
	pool   *pgxpool.Pool // global: reads, and writes when outbox is nil
	outbox *pgxpool.Pool // regional: when set, Log stages rows here for the Relay
}
func NewDomainAudit(pool *pgxpool.Pool) *DomainAudit {
	return &DomainAudit{pool: pool}
}
// NewDomainAuditWithOutbox reads from the global pool but stages writes in the
// regional outbox, keeping the request path off the cross-region global
// cluster. Pair it with a Relay draining the same two pools.
func NewDomainAuditWithOutbox(global, regional *pgxpool.Pool) *DomainAudit {
	return &DomainAudit{pool: global, outbox: regional}
}
// Log writes a domain audit event. Best-effort — callers should log errors
// but not fail the request.
func (d *DomainAudit) Log(ctx context.Context, actorAccountID model.AccountID, eventType, resourceType, resourceID string, meta map[string]any) error {
	if meta == nil {
		meta = map[string]any{}
	}
	metaJSON, err := json.Marshal(meta)
	if err != nil {
		return fmt.Errorf("marshal audit metadata: %w", err)
	}
	db, table := d.pool, "domain_audit_events"
	if d.outbox != nil {
		db, table = d.outbox, outboxTable
	}
	_, err = db.Exec(ctx,
		`INSERT INTO `+table+` (id, actor_account_id, event_type, resource_type, resource_id, metadata)
         VALUES ($1, $2, $3, $4, $5, $6)`,
		model.NewID().String(), actorAccountID.String(), eventType, resourceType, resourceID, metaJSON,
	)
	if err != nil {
		return fmt.Errorf("insert domain audit event: %w", err)
	}
	return nil
}
// DomainAuditEvent is a control-plane event from the global audit log.
type DomainAuditEvent struct {
	ID             string         `json:"id"`
	ActorAccountID string         `json:"actor_account_id"`
	EventType      string         `json:"event_type"`
	ResourceType   string         `json:"resource_type"`
	ResourceID     string         `json:"resource_id"`
	Metadata       map[string]any `json:"metadata"`
	CreatedAt      time.Time      `json:"created_at"`
}
// ResourceRef names one audited subject: a resource type together with an id of
// that type (e.g. "repo" + its ULID). Both halves are required. Ids are unique
// per type rather than globally, so an id alone would match rows of unrelated
// types — the pair is the smallest thing that identifies a subject, which is why
// it travels as one value instead of two independently-settable fields.
type ResourceRef struct {
	Type string
	ID   string
}
// EventFilter narrows a domain-audit query. A zero value matches every event;
// each set field ANDs one more constraint.
type EventFilter struct {
	ActorAccountID string
	// Resource scopes the query to one subject; nil applies no resource
	// constraint.
	Resource   *ResourceRef
	EventTypes []string
}
// where renders the filter as a SQL WHERE clause (empty string when the filter
// is a zero value), appending each bound value to args. Shared by the list and
// count paths so a filter can never apply to one but not the other.
//
// A half-populated Resource is an error rather than a dropped constraint:
// omitting it would silently widen the query to every resource, the opposite of
// what a scoped read asked for.
func (f EventFilter) where(args *[]any) (string, error) {
	var conds []string
	if f.ActorAccountID != "" {
		*args = append(*args, f.ActorAccountID)
		conds = append(conds, fmt.Sprintf("actor_account_id = $%d", len(*args)))
	}
	if r := f.Resource; r != nil {
		if r.Type == "" || r.ID == "" {
			return "", fmt.Errorf("resource filter needs both type and id, got type=%q id=%q", r.Type, r.ID)
		}
		*args = append(*args, r.Type)
		conds = append(conds, fmt.Sprintf("resource_type = $%d", len(*args)))
		*args = append(*args, r.ID)
		conds = append(conds, fmt.Sprintf("resource_id = $%d", len(*args)))
	}
	if len(f.EventTypes) > 0 {
		*args = append(*args, f.EventTypes) // pgx binds []string as a SQL array
		conds = append(conds, fmt.Sprintf("event_type = ANY($%d)", len(*args)))
	}
	if len(conds) == 0 {
		return "", nil
	}
	return " WHERE " + strings.Join(conds, " AND "), nil
}
// ListEvents returns a page of domain audit events, ordered by time
// descending. If actorAccountID is non-empty, only events for that actor are
// returned. If eventTypes is non-empty, only events whose type is in the set
// are returned; empty/nil applies no type constraint.
func (d *DomainAudit) ListEvents(ctx context.Context, limit, offset int, actorAccountID string, eventTypes []string) ([]*DomainAuditEvent, error) {
	return d.ListEventsFiltered(ctx, limit, offset, EventFilter{
		ActorAccountID: actorAccountID,
		EventTypes:     eventTypes,
	})
}
// ListEventsFiltered is ListEvents with the full filter surface, including
// resource scoping — the form a resource-scoped read path needs.
func (d *DomainAudit) ListEventsFiltered(ctx context.Context, limit, offset int, filter EventFilter) ([]*DomainAuditEvent, error) {
	var args []any
	where, err := filter.where(&args)
	if err != nil {
		return nil, err
	}
	query := `SELECT id, actor_account_id, event_type, resource_type, resource_id, metadata, created_at
		 FROM domain_audit_events`
	query += where
	args = append(args, limit)
	query += fmt.Sprintf(" ORDER BY created_at DESC LIMIT $%d", len(args))
	args = append(args, offset)
	query += fmt.Sprintf(" OFFSET $%d", len(args))
	rows, err := d.pool.Query(ctx, query, args...)
	if err != nil {
		return nil, fmt.Errorf("query domain audit events: %w", err)
	}
	defer rows.Close()
	var events []*DomainAuditEvent
	for rows.Next() {
		e := &DomainAuditEvent{}
		var metaJSON []byte
		if err := rows.Scan(&e.ID, &e.ActorAccountID, &e.EventType, &e.ResourceType, &e.ResourceID, &metaJSON, &e.CreatedAt); err != nil {
			return nil, fmt.Errorf("scan domain audit event: %w", err)
		}
		if metaJSON != nil {
			if uerr := json.Unmarshal(metaJSON, &e.Metadata); uerr != nil {
				e.Metadata = map[string]any{"_parse_error": uerr.Error()}
			}
		}
		events = append(events, e)
	}
	if err := rows.Err(); err != nil {
		return nil, fmt.Errorf("iterate domain audit events: %w", err)
	}
	return events, nil
}
// CountEvents returns the total number of domain audit events, applying the
// same optional actor and event-type filters as ListEvents.
func (d *DomainAudit) CountEvents(ctx context.Context, actorAccountID string, eventTypes []string) (int, error) {
	return d.CountEventsFiltered(ctx, EventFilter{
		ActorAccountID: actorAccountID,
		EventTypes:     eventTypes,
	})
}
// CountEventsFiltered is CountEvents with the full filter surface.
func (d *DomainAudit) CountEventsFiltered(ctx context.Context, filter EventFilter) (int, error) {
	var args []any
	where, err := filter.where(&args)
	if err != nil {
		return 0, err
	}
	query := `SELECT count(*) FROM domain_audit_events` + where
	var count int
	if err := d.pool.QueryRow(ctx, query, args...).Scan(&count); err != nil {
		return 0, fmt.Errorf("count domain audit events: %w", err)
	}
	return count, nil
}
// DistinctEventTypes returns every distinct event type present in the global
// audit log, sorted ascending. Event types are bare string literals at each
// call site — there is no central enum — so the available set can only be
// discovered dynamically.
func (d *DomainAudit) DistinctEventTypes(ctx context.Context) ([]string, error) {
	rows, err := d.pool.Query(ctx, `SELECT DISTINCT event_type FROM domain_audit_events ORDER BY event_type`)
	if err != nil {
		return nil, fmt.Errorf("query distinct domain audit event types: %w", err)
	}
	defer rows.Close()
	var types []string
	for rows.Next() {
		var t string
		if err := rows.Scan(&t); err != nil {
			return nil, fmt.Errorf("scan distinct domain audit event type: %w", err)
		}
		types = append(types, t)
	}
	if err := rows.Err(); err != nil {
		return nil, fmt.Errorf("iterate distinct domain audit event types: %w", err)
	}
	return types, nil
}

