func (d *DomainAudit) ListEvents(ctx context.Context, limit, offset int, actorAccountID string, eventTypes []string) ([]*DomainAuditEvent, error) {
	return d.ListEventsFiltered(ctx, limit, offset, EventFilter{
		ActorAccountID: actorAccountID,
		EventTypes:     eventTypes,
	})
}
// ListEventsFiltered is ListEvents with the full filter surface, including
// resource scoping — the form a resource-scoped read path needs.
func (d *DomainAudit) ListEventsFiltered(ctx context.Context, limit, offset int, filter EventFilter) ([]*DomainAuditEvent, error) {
	var args []any
	where, err := filter.where(&args)
	if err != nil {
		return nil, err
	}
	query := `SELECT id, actor_account_id, event_type, resource_type, resource_id, metadata, created_at
		 FROM domain_audit_events`
	query += where
	args = append(args, limit)
	query += fmt.Sprintf(" ORDER BY created_at DESC LIMIT $%d", len(args))
	args = append(args, offset)
	query += fmt.Sprintf(" OFFSET $%d", len(args))
	rows, err := d.pool.Query(ctx, query, args...)
	if err != nil {
		return nil, fmt.Errorf("query domain audit events: %w", err)
	}
	defer rows.Close()
	var events []*DomainAuditEvent
	for rows.Next() {
		e := &DomainAuditEvent{}
		var metaJSON []byte
		if err := rows.Scan(&e.ID, &e.ActorAccountID, &e.EventType, &e.ResourceType, &e.ResourceID, &metaJSON, &e.CreatedAt); err != nil {
			return nil, fmt.Errorf("scan domain audit event: %w", err)
		}
		if metaJSON != nil {
			if uerr := json.Unmarshal(metaJSON, &e.Metadata); uerr != nil {
				e.Metadata = map[string]any{"_parse_error": uerr.Error()}
			}
		}
		events = append(events, e)
	}
	if err := rows.Err(); err != nil {
		return nil, fmt.Errorf("iterate domain audit events: %w", err)
	}
	return events, nil
}
// CountEvents returns the total number of domain audit events, applying the
// same optional actor and event-type filters as ListEvents.
func (d *DomainAudit) CountEvents(ctx context.Context, actorAccountID string, eventTypes []string) (int, error) {
	return d.CountEventsFiltered(ctx, EventFilter{
		ActorAccountID: actorAccountID,
		EventTypes:     eventTypes,
	})
}
// CountEventsFiltered is CountEvents with the full filter surface.
func (d *DomainAudit) CountEventsFiltered(ctx context.Context, filter EventFilter) (int, error) {
	var args []any
	where, err := filter.where(&args)
	if err != nil {
		return 0, err
	}
	query := `SELECT count(*) FROM domain_audit_events` + where
	var count int
	if err := d.pool.QueryRow(ctx, query, args...).Scan(&count); err != nil {
		return 0, fmt.Errorf("count domain audit events: %w", err)
	}
	return count, nil
}
// DistinctEventTypes returns every distinct event type present in the global
// audit log, sorted ascending. Event types are bare string literals at each
// call site — there is no central enum — so the available set can only be
// discovered dynamically.
func (d *DomainAudit) DistinctEventTypes(ctx context.Context) ([]string, error) {
	rows, err := d.pool.Query(ctx, `SELECT DISTINCT event_type FROM domain_audit_events ORDER BY event_type`)
	if err != nil {
		return nil, fmt.Errorf("query distinct domain audit event types: %w", err)
	}
	defer rows.Close()
	var types []string
	for rows.Next() {
		var t string
		if err := rows.Scan(&t); err != nil {
			return nil, fmt.Errorf("scan distinct domain audit event type: %w", err)
		}
		types = append(types, t)
	}
	if err := rows.Err(); err != nil {
		return nil, fmt.Errorf("iterate distinct domain audit event types: %w", err)
	}
	return types, nil
}

