package nativemirror

// Durable native_mirror.created delivery (COR-1359). Service.Announce enqueues
// the fully marshaled event in the same transaction as the seeded→announced
// CAS; this relay publishes each jurisdiction's rows through JetStream and
// deletes a row only after a positive PubAck, so a crash anywhere between the
// announce commit and the publish re-delivers. Duplicates are absorbed by the
// stream's msg-id dedup window and, past it, by the consumer's idempotence.
//
// Drain model: per-replica polling with FOR UPDATE under a short lock_timeout.
// Regional entire-core is HPA-scaled, so the row lock keeps two pods of one
// region from publishing the same batch. A pod that cannot get the lock in time
// treats the tick as empty. The claim reads through the jurisdiction index, so
// it never scans or locks another region's rows (trail 3897: a full scan with
// SKIP LOCKED let remote relays hide AU rows from the AU relay). The publish and
// the post-ack DELETE both happen inside the claiming transaction, because the
// claim's lock is gone the moment that transaction ends. A PubAck inside the
// transaction is fine: a commit failure after the ack leaves the row, and the
// republish dedupes.

import (
	"context"
	"errors"
	"fmt"
	"log/slog"
	"sync"
	"time"

	"github.com/jackc/pgx/v5/pgxpool"
	"go.opentelemetry.io/otel"
