	"entire.io/core/model"
	"entire.io/core/observability"
	"entire.io/slogutil"
)

// createdEventMsgID is the JetStream deduplication key for a placement's
// created event — one placement, one created event, so the repo ULID alone
// disambiguates.
func createdEventMsgID(id model.RepoID) string {
	return "native_mirror.created/" + id.String()
}

