// Written by Service.Announce, reaped by Service.Delete (teardown), drained
// here.
const createdOutboxTable = "native_mirror_created_outbox"

// createdOutboxJurisdictionIndex is the (jurisdiction, created_at) index.
const createdOutboxJurisdictionIndex = "native_mirror_created_outbox_jurisdiction_created_idx"

const (
	createdRelayInterval = 15 * time.Second
	createdRelayBatch    = 100
	// createdRelayCommitGrace bounds the post-publish DELETE+commit on a
	// detached context, so a shutdown mid-drain doesn't roll back row cleanup
	// for events that already acked (they'd be republished — harmless, but
	// noisy — on the next pod's first drain).
	createdRelayCommitGrace = 5 * time.Second
	// createdRelayLockTimeout bounds the claim's wait on a row another pod of
	// this region holds. A timeout means that pod is draining the batch.
	createdRelayLockTimeout = "2s"
	// createdRelayPublishTimeout bounds one PubAck wait, below
	// natsmsg.DefaultPublishTimeout and createdRelayCommitGrace, so a slow
	// stream releases the claimed rows sooner.
	createdRelayPublishTimeout = 2 * time.Second
	// createdRelayStallTicks is how many consecutive ticks may see pending rows
	// but claim none before the relay reports a stall.
	createdRelayStallTicks = 4
)

// sqlstateLockNotAvailable is returned when lock_timeout expires.
const sqlstateLockNotAvailable = "55P03"

// CreatedOutboxPublisher is the acknowledged raw-publish surface the relay
// needs. *resourceevents.Emitter satisfies it (PublishAckMsg); it may be
// disabled — rows then remain queued and the backlog telemetry exposes the gap.
type CreatedOutboxPublisher interface {
	PublishAckMsg(ctx context.Context, msgID, subject string, payload []byte) error
}

// CreatedOutboxRelay drains one jurisdiction's pending native_mirror.created
// events from the global native-mirrors database.
type CreatedOutboxRelay struct {
	coverage     *observability.Coverage
	pool         *pgxpool.Pool
	jurisdiction string
