// and the jurisdiction whose rows it drains.
func NewCreatedOutboxRelay(pool *pgxpool.Pool, jurisdiction string, publisher CreatedOutboxPublisher) *CreatedOutboxRelay {
	return &CreatedOutboxRelay{
		pool:         pool,
		jurisdiction: jurisdiction,
		publisher:    publisher,
		interval:     createdRelayInterval,
		batch:        createdRelayBatch,
	}
}

