import (
	"context"
	"encoding/json"
	"errors"
	"fmt"
	"log/slog"
	"time"

	"github.com/jackc/pgx/v5"
	"github.com/jackc/pgx/v5/pgxpool"
	"go.opentelemetry.io/otel"
	"go.opentelemetry.io/otel/attribute"
	"go.opentelemetry.io/otel/metric"

	"entire.io/api/corev1"
	"entire.io/core/model"
	"entire.io/core/resourceevents"
	"entire.io/slogutil"
)

const (
	eventRelayInterval = 15 * time.Second
	eventRelayBatch    = 100
)

// EventPublisher is the acknowledged publish the relay needs.
// *resourceevents.Emitter satisfies it.
type EventPublisher interface {
	PublishAckMsg(ctx context.Context, msgID, subject string, payload []byte) error
}

// ProjectDisplayLookup resolves names and forges for installation events.
// *resource.Store.ProjectDisplayMetadata satisfies it.
type ProjectDisplayLookup func(ctx context.Context, projectIDs []model.ProjectID) (map[model.ProjectID]model.ProjectDisplayMetadata, error)

// EventRelay publishes one jurisdiction's installation events to its local
// stream.
type EventRelay struct {
	pool         *pgxpool.Pool
