// Package repodeletion owns the durable repo.deleted lifecycle outbox.
//
// Authoritative repo stores enqueue in the same transaction that removes their
// final retry anchor. Relays publish at least once through JetStream and delete
// an outbox row only after PubAck. A crash after the ack but before row cleanup
// therefore produces a harmless duplicate on restart.
package repodeletion

import (
	"context"
	"errors"
	"fmt"
	"log/slog"
	"time"

	"github.com/jackc/pgx/v5"
	"github.com/jackc/pgx/v5/pgxpool"

	"entire.io/core/model"
	"entire.io/core/resourceevents"
	"entire.io/slogutil"
)

const (
	defaultRelayInterval = 15 * time.Second
	defaultBatchSize     = 100
)

const (
	regionalOutboxTable     = "repo_deletion_outbox"
	nativeMirrorOutboxTable = "native_mirror_deletion_outbox"
)

// Publisher is the acknowledged lifecycle surface used by Relay.
// *resourceevents.Emitter satisfies it.
type Publisher interface {
	PublishAck(ctx context.Context, msgID, resourceType, resourceID, op, actorID string, opts ...resourceevents.PublishOption) error
}

// Outbox binds durable enqueue operations to one database and jurisdiction.
// The same type is used over the regional repos database and the global
// native_mirrors database.
type Outbox struct {
	pool         *pgxpool.Pool
	jurisdiction string
	table        string
	source       string
}

// NewRegional binds the outbox co-located with authoritative regional repos.
func NewRegional(pool *pgxpool.Pool, jurisdiction string) *Outbox {
	return &Outbox{pool: pool, jurisdiction: jurisdiction, table: regionalOutboxTable, source: "regional_repo"}
}

// NewNativeMirror binds the outbox co-located with global native-mirror
// intents. A distinct table is required because the two authoritative stores
// live in different databases with separate migration sets.
func NewNativeMirror(pool *pgxpool.Pool, jurisdiction string) *Outbox {
	return &Outbox{pool: pool, jurisdiction: jurisdiction, table: nativeMirrorOutboxTable, source: "native_mirror"}
}

// EnqueueInTx records a repo deletion in the caller's authoritative delete
// transaction. Repo ULIDs are never reused, so one row per repo is sufficient
// and retries are idempotent.
func (o *Outbox) EnqueueInTx(ctx context.Context, tx pgx.Tx, repoID model.RepoID) error {
	if o == nil {
		return nil
	}
	if _, err := tx.Exec(ctx,
		`INSERT INTO `+o.table+` (repo_id, jurisdiction)
		 VALUES ($1, $2)
		 ON CONFLICT (repo_id) DO NOTHING`,
		repoID, o.jurisdiction,
	); err != nil {
		return fmt.Errorf("enqueue repo deletion %s: %w", repoID, err)
	}
	return nil
}

