// DrainOnce publishes each of this jurisdiction's events whose earlier
// revisions are already published, and deletes it after the PubAck. It takes
// no row locks: replicas can publish one event twice, and the stream's msg-id
// window drops the copy. A failed publish leaves the row, and it holds back
// only later revisions of the same installation.
func (r *EventRelay) DrainOnce(ctx context.Context) (int, error) {
	rows, err := r.pool.Query(ctx,
		`SELECT `+pendingColumns+` FROM `+eventOutboxTable+` o
		 WHERE o.jurisdiction = $1
		   AND NOT EXISTS (
		       SELECT 1 FROM `+eventOutboxTable+` e
		       WHERE e.installation_id = o.installation_id AND e.revision < o.revision)
		 ORDER BY o.created_at, o.installation_id
		 LIMIT $2`,
		r.jurisdiction, r.batch)
	if err != nil {
		return 0, fmt.Errorf("select installation events: %w", err)
	}
	batch, err := scanPending(rows)
	if err != nil {
		return 0, err
	}

	var (
		published int
		errs      []error
	)
	payloads := make([][]byte, len(batch))
	for i, p := range batch {
		payload, err := p.rendered(ctx, r.pool)
		if err != nil {
			errs = append(errs, fmt.Errorf("render installation %s revision %d: %w", p.installationID, p.revision, err))
			continue
		}
		payloads[i] = payload
	}
	r.stamp(ctx, payloads)
	for i, p := range batch {
		payload := payloads[i]
		if payload == nil {
			continue
		}
		if err := r.publisher.PublishAckMsg(ctx, eventMsgID(p.installationID, p.revision), p.subject, payload); err != nil {
			errs = append(errs, fmt.Errorf("publish installation %s revision %d: %w", p.installationID, p.revision, err))
			continue
		}
		if _, err := r.pool.Exec(ctx,
			`DELETE FROM `+eventOutboxTable+` WHERE installation_id = $1 AND revision = $2`,
			p.installationID, p.revision,
		); err != nil {
			errs = append(errs, fmt.Errorf("delete published installation %s revision %d; it stays queued and is republished: %w", p.installationID, p.revision, err))
			continue
		}
		published++
	}
	return published, errors.Join(errs...)
}

