// outboxTable is the identity-plane table holding un-relayed email events.
const outboxTable = "email_outbox"

const (
	// defaultRelayInterval is how often the relay drains the outbox.
	// Transactional email is not latency-critical to the second, so ~1s of
	// publish latency is irrelevant.
	defaultRelayInterval = 1 * time.Second
	defaultRelayBatch    = 128

	commitGracePeriod = 5 * time.Second

	// backlogSampleInterval is how often Run samples the per-jurisdiction
	// backlog gauges. The OTLP reader exports on its own (~60s) cadence, so
	// sampling faster than that only adds DB reads.
	backlogSampleInterval = 30 * time.Second
)

// Publisher is the JetStream publish surface the relay needs. *nats.JetStreamContext
// satisfies it; tests substitute a fake.
type Publisher interface {
	PublishMsg(m *nats.Msg, opts ...nats.PubOpt) (*nats.PubAck, error)
}

// Outbox enqueues email events. Enqueue writes one row per event; the Relay
// publishes and deletes it post-commit, so an event reaches the stream at
// least once iff its row committed.
type Outbox struct {
	pool *pgxpool.Pool
}

// NewOutbox builds an Outbox over the identity-plane pool.
func NewOutbox(pool *pgxpool.Pool) *Outbox { return &Outbox{pool: pool} }

// outboxRegionStampSQL derives crdb_region from home_jurisdiction, bound as
// $4 in both INSERTs. See Enqueue for the invariant it preserves.
const outboxRegionStampSQL = `COALESCE(
	     (SELECT min(default_to_database_primary_region(cell)) FROM clusters
	       WHERE jurisdiction = $4 AND decommissioned_at IS NULL),
	     default_to_database_primary_region(gateway_region())
	 )::crdb_internal_region`

// Enqueue durably records an email event. It writes on the transaction
// carried by ctx (pgutil.TxFromContext) when one is present, so the caller
// can enqueue atomically with the domain change that triggers the email
// (e.g. a waitlist join or approval): the event is then published iff that
// change actually committed. Falls back to the pool if ctx carries no
// transaction.
//
// crdb_region is stamped explicitly rather than left to the column's
// gateway-homing default: region becomes a pure function of
// home_jurisdiction, which is what legalizes the claim's crdb_region
// predicate (COR-1079; the same deterministic-homing invariant mirror
// placements adopted in mirrorrepo/019). min() is needed here where
// mirrorrepo's Create needs none: a placement names one cluster_slug, but a
// jurisdiction can own several clusters, potentially in several regions —
// min() picks one deterministically, and since the claim predicates on the
// FULL region set of the jurisdiction (jurisdictionRegions), the chosen one
// is always covered.
//
// The COALESCE arm falls back to gateway homing only when the jurisdiction
// has no live clusters row at all. Those rows stay claimable for as long as that
// holds: jurisdictionRegions returns an empty set for such a jurisdiction,
// which leaves the claim unpredicated. If a clusters row later appears and
// fold(its cell) differs from the gateway region these rows were homed in, they
// stop matching the now-predicated claim — same stranding class as a cell
// rehome (see RecordBacklog), and about as rare.
//
// decommissioned_at IS NULL: clusters keeps decommissioned rows (core/cluster's
// reconcile stamps the column, it does not delete), and a decommissioned cluster
// can no longer home work. This filter MUST stay identical to
// jurisdictionRegions' — the deterministic-homing invariant is that the claim's
// region set is computed over the same clusters population this stamp folds
// over. Both INSERTs stamp through outboxRegionStampSQL, so there is one copy
// to keep in step.
//
// clusters is a GLOBAL table (resource/026), so the subquery is a local read
// in every region and adds no cross-region hop to the caller's transaction.
func (o *Outbox) Enqueue(ctx context.Context, eventID string, accountID model.AccountID, kind Kind, homeJurisdiction string) error {
	var db pgutil.DBTX = o.pool
	if tx := pgutil.TxFromContext(ctx); tx != nil {
