	}
	if _, err := db.Exec(ctx,
		`INSERT INTO `+outboxTable+` (event_id, account_id, kind, home_jurisdiction, crdb_region)
		 VALUES ($1, $2, $3, $4, `+outboxRegionStampSQL+`)`,
		eventID, accountID.String(), string(kind), homeJurisdiction,
	); err != nil {
		return fmt.Errorf("enqueue email event: %w", err)
	}
