	Enqueue(ctx context.Context, sub Subject, homeJurisdiction string) error
	Pending(ctx context.Context, jurisdiction string, limit int) ([]PendingEnsure, error)
	Retry(ctx context.Context, sub Subject, attempts int, next time.Time) error
	Done(ctx context.Context, sub Subject) error
	Drop(ctx context.Context, sub Subject) error
}

type GlobalEnsureStore struct {
	pool *pgxpool.Pool
}

var _ EnsureStore = (*GlobalEnsureStore)(nil)

func NewGlobalEnsureStore(pool *pgxpool.Pool) *GlobalEnsureStore {
	return &GlobalEnsureStore{pool: pool}
}

func (s *GlobalEnsureStore) Ensured(ctx context.Context, sub Subject) (bool, error) {
	var ok bool
	err := s.pool.QueryRow(ctx,
		`SELECT true FROM billing_ensured WHERE subject_type = $1 AND subject_id = $2`,
		sub.Type, sub.ID).Scan(&ok)
	if errors.Is(err, pgx.ErrNoRows) {
		return false, nil
	}
	if err != nil {
		return false, fmt.Errorf("read billing ensured marker: %w", err)
	}
	return ok, nil
}

