// Package accounterasure carries multi-region account erasure over the global
// CRDB — no NATS (ADR 20260708).
//
// When the reaper finalizes an account it enqueues one durable row in the
// global-core outbox (Outbox.EnqueueInTx, in the SAME transaction as the
// identity delete — so the row exists iff the account was actually deleted).
// Each regional core runs a Poller against that global outbox: it claims rows
// its region has not yet erased, runs the region-local erase
// (RegionEraser.EraseAccountRegion — this region's PII, its own-cluster repos,
// github tokens), and records its jurisdiction in the row's completion set. The
// row is deleted only once EVERY deployed jurisdiction has recorded, so it is a
// durable backstop that never ages out and a region that falls behind stays
// visible as an un-drained row.
//
// The hand-off needs no NATS and no cross-region mesh: every regional core
// already holds a connection to the global pool where the outbox lives, and the
// region-local erase is idempotent and keyed on the account ULID, so a region
// finishes even after the global identity row is gone and a re-drain is a safe
// no-op.
package accounterasure

import (
	"context"
	"errors"
	"fmt"
	"log/slog"
	"slices"
	"time"

	"github.com/jackc/pgx/v5"
	"github.com/jackc/pgx/v5/pgxpool"
	"go.opentelemetry.io/otel"
	"go.opentelemetry.io/otel/attribute"
	"go.opentelemetry.io/otel/metric"

	"entire.io/core/model"
	"entire.io/internal/pgutil"
	"entire.io/slogutil"
)

// outboxTable is the global-core table holding un-erased account rows.
const outboxTable = "account_erasure_outbox"

const (
	// defaultPollInterval is how often a region's poller drains the outbox.
	// Erasure is a background, cooldown-delayed operation and rows only appear
	// after the daily reaper pass, so a minute of latency is irrelevant; the
	// table is empty the rest of the time, so the poll is near-free.
	defaultPollInterval = 60 * time.Second
	defaultPollBatch    = 128
)

// RegionEraser runs the region-local half of account erasure against THIS
// region's stores: delete the account's regional PII and reap its repos in this
// region's clusters (and best-effort sweep the now-empty account-owned project
// rows). Must be idempotent — a region may run it more than once (retries,
// concurrent replicas, redelivery after the global identity row is gone).
// *api.Server satisfies it.
type RegionEraser interface {
	EraseAccountRegion(ctx context.Context, accountID model.AccountID) error
}

// JurisdictionLister reports the set of deployed jurisdictions — the regions
// whose acks an outbox row must collect before it is complete. Backed by the
// global cluster registry (*cluster.Store.DeployedJurisdictions).
type JurisdictionLister interface {
	DeployedJurisdictions(ctx context.Context) ([]string, error)
}

// Outbox enqueues erasure rows. Enqueue writes one row per account; regional
// pollers drain it and delete the row once every region has erased.
type Outbox struct {
	pool *pgxpool.Pool
}

// NewOutbox builds an Outbox over the global-core pool.
func NewOutbox(pool *pgxpool.Pool) *Outbox { return &Outbox{pool: pool} }

// Enqueue durably records an erasure row for accountID on the transaction
// carried by ctx (pgutil.ContextWithTx) when one is present — so the caller can
// enqueue atomically with the account's identity deletion — else on the pool.
func (o *Outbox) Enqueue(ctx context.Context, accountID model.AccountID, homeJurisdiction string) error {
	var db pgutil.DBTX = o.pool
	if tx := pgutil.TxFromContext(ctx); tx != nil {
		db = tx
	}
	_, err := db.Exec(ctx,
		`INSERT INTO `+outboxTable+` (account_id, home_jurisdiction) VALUES ($1, $2)`,
		accountID.String(), homeJurisdiction,
	)
	if err != nil {
		return fmt.Errorf("enqueue erasure row: %w", err)
	}
	return nil
}

// EnqueueInTx enqueues the erasure row and runs within — the account's identity
// deletion — in ONE transaction on the outbox's (global) pool. Because the
// outbox and the identity tables share that pool, the row and the identity
// deletion commit atomically: a region erases iff the account was actually
// deleted, closing the window where a failed or reactivated teardown would still
// drive an irreversible erasure. within must use the transaction carried by ctx
// (identity.Store.DeleteAccount does).
func (o *Outbox) EnqueueInTx(ctx context.Context, accountID model.AccountID, homeJurisdiction string, within func(ctx context.Context) error) error {
	if err := pgutil.RunInTx(ctx, o.pool, func(ctx context.Context) error {
		if err := o.Enqueue(ctx, accountID, homeJurisdiction); err != nil {
			return err
		}
		return within(ctx)
	}); err != nil {
		return fmt.Errorf("enqueue erasure row in tx: %w", err)
	}
	return nil
}

// Poller mints a per-region drainer over this outbox's pool. jurisdiction is
// this core's region; eraser runs the region-local erase; lister reports the
// deployed jurisdictions whose acks a row must collect before deletion.
func (o *Outbox) Poller(jurisdiction string, eraser RegionEraser, lister JurisdictionLister) *Poller {
	return &Poller{
		pool:         o.pool,
		jurisdiction: jurisdiction,
		eraser:       eraser,
		lister:       lister,
		interval:     defaultPollInterval,
		batch:        defaultPollBatch,
	}
}

// Poller drains the erasure outbox from the global CRDB for ONE region. It
// replaces the NATS fan-out relay + consumer (ADR 20260708).
type Poller struct {
	pool         *pgxpool.Pool
	jurisdiction string
	eraser       RegionEraser
	lister       JurisdictionLister
	interval     time.Duration
	batch        int
	onComplete   CompletionHook
}

