// (e.g. a service-account principal, which never carries org memberships) are
// a silent no-op — UPDATE of zero rows is not an error.
func bumpMembershipsVersion(ctx context.Context, db execer, accountIDs ...model.AccountID) error {
	if len(accountIDs) == 0 {
		return nil
	}
	ids := make([]string, len(accountIDs))
	for i, id := range accountIDs {
		ids[i] = id.String()
	}
	if _, err := db.Exec(ctx,
		`UPDATE accounts SET memberships_version = memberships_version + 1 WHERE id = ANY($1)`,
		ids,
	); err != nil {
		return fmt.Errorf("bump memberships_version: %w", err)
	}
	return nil
}

// orgQuotaLimit and projectQuotaLimit are the sole policy hooks for the
// hard-coded initial quotas. Per-owner persisted overrides can replace their
// bodies without changing resource-service or API call signatures.
func (s *Store) orgQuotaLimit(_ context.Context, _ model.AccountID) (int, error) {
	return defaultHumanOwnedOrgsPerAccount, nil
}

func (s *Store) projectQuotaLimit(_ context.Context, _ string, _ model.ID) (int, error) {
	return DefaultHumanProjectsPerOwner, nil
}

// Store implements Service backed by CockroachDB. It takes an
// authz.Service dependency to write SpiceDB relations when
// resources are created or access is modified.
type Store struct {
	pool  *pgxpool.Pool
	authz authz.Service
	// electInProcessingCell limits new primary choices to the project's
	// primary processing cell; see WithProcessingCellElection.
	electInProcessingCell bool
	// followerAOSTPin replaces the AS OF SYSTEM TIME clause spliced into this
	// store's follower reads. Empty in production (and unreachable from outside
	// the package) — tests pin it to a fixed historical timestamp so the
	// stale-read error path is reachable without racing however far
	// follower_read_timestamp() happens to lag. See export_test.go.
	followerAOSTPin postgres.AOST
	// reads selects the follower-read clause; see postgres.FollowerReads. An
	// explicit followerAOSTPin still wins.
	reads postgres.FollowerReads
	// afterReservedNameGrantCheckForTest runs between CreateProject's grant
	// pre-check and the create statement. Nil in production and unreachable
	// from outside the package — it is the only way to close that window
	// deterministically, and the branch it reaches decides whether a caller
	// who lost the grant is told the name is reserved or that it is over
	// quota. See export_test.go.
	afterReservedNameGrantCheckForTest func(context.Context)
}

// followerAOST is the AS OF SYSTEM TIME clause every follower read of this store
// splices in: postgres.FollowerReadAOST unless a test pinned it.
// snapshotAOST reads at the caller's commit timestamp, or from the nearest
// replica when it has none. Neither arm reaches the leaseholder.
//
// Every *Snapshot read below is built on this and shares one contract: the
// caller's own write is in that snapshot by construction, so the answer is
// authoritative and there is no fresh-on-miss or fresh-on-empty retry. That
// retry is exactly what the *FollowerRead counterparts exist to do.
func (s *Store) snapshotAOST(token postgres.CommitToken) postgres.AOST {
	if token == "" {
		return s.followerAOST()
	}
	return postgres.AOSTAt(token)
}

func (s *Store) followerAOST() postgres.AOST {
	if s.followerAOSTPin != "" {
		return s.followerAOSTPin
	}
	return s.reads.AOST()
}

var _ Service = (*Store)(nil)

func NewStore(pool *pgxpool.Pool, authzSvc authz.Service, opts ...Option) *Store {
	s := &Store{pool: pool, authz: authzSvc}
	for _, opt := range opts {
		opt(s)
	}
	return s
}

// Option configures a Store.
type Option func(*Store)

// WithProcessingCellElection limits each new processing-primary choice, each
// admin override, and each new Entire data primary to placements in the owning
// project's primary processing cell
// (ADR 20260909-project-primary-processing-cell). A current primary that is
// still eligible stays, so a group whose primary is in another cell keeps it.
// A project without a cell elects as before.
func WithProcessingCellElection(enabled bool) Option {
	return func(s *Store) { s.electInProcessingCell = enabled }
}

// WithFollowerReadsForTest restores the production follower-read clause
// under NewStoreForTest.
func WithFollowerReadsForTest() Option {
	return func(s *Store) { s.reads = postgres.FollowerReads{} }
}

// NewStoreForTest is NewStore with follower reads served fresh; see
// postgres.FreshFollowerReadsForTest. A test of the follower clause itself
// adds WithFollowerReadsForTest.
func NewStoreForTest(pool *pgxpool.Pool, authzSvc authz.Service, opts ...Option) *Store {
	s := &Store{pool: pool, authz: authzSvc, reads: postgres.FreshFollowerReadsForTest()}
	for _, opt := range opts {
		opt(s)
	}
	return s
}

// --- Orgs ---

// CreateOrg creates a human-owned org. normalizeOrgName trims and validates
// the name to the same shape as a project name, which also rejects any name
// containing ':' — that reserves the ':' namespace for system-managed orgs
// (e.g. "entire:system", "gh:<github-org-id>") so a human can never create an
// org whose name collides with one. It also refuses Entire's own names
// (reservedOrgNames) with ErrReservedName. Trusted callers that need a
// reserved name use CreateOrgWithoutValidation.
func (s *Store) CreateOrg(ctx context.Context, name, region string, ownerAccountID model.AccountID) (OrgCreation, error) {
	name, err := normalizeOrgName(name)
	if err != nil {
		return OrgCreation{}, err
	}
	return s.createOrg(ctx, name, region, ownerAccountID, true)
}

// CreateOrgWithoutValidation creates an org while SKIPPING all name
// validation: the ':' namespace check and the reserved-name check.
//
// DANGER: this is the backdoor that the validated CreateOrg exists to close.
// It is the ONLY way to mint an org in the reserved ':' namespace
// (e.g. serviceaccount.SystemOrgName "entire:system") or with a reserved
// name. Call it ONLY with a name your own code
// constructs — NEVER with a user- or attacker-supplied string, or a human
// can squat a system org name and hijack it.
func (s *Store) CreateOrgWithoutValidation(ctx context.Context, name, region string, ownerAccountID model.AccountID) (*model.Org, error) {
	created, err := s.createOrg(ctx, name, region, ownerAccountID, false)
	return created.Org, err
}

// createOrgSQL runs as a single implicit transaction (no explicit
// BEGIN/COMMIT): CockroachDB retries it server-side on a serialization
// conflict as long as its result hasn't started streaming, which a one-row
// result never does. $5 is the quota limit; NULL disables it. $8 enforces
// the lifetime ledger on accounts and stamps the org's creation ordinal;
// a NULL org_creation_limit or no row (test fixtures) skips the cap.
const createOrgSQL = `WITH owned AS (
	SELECT count(*) AS n
	FROM memberships m JOIN orgs o ON o.id = m.org_id
	WHERE m.account_id = $1 AND m.role = 'owner' AND m.status = 'active'
	  AND strpos(o.name, ':') = 0
),
ledger AS (
	SELECT org_creations, org_creation_limit FROM accounts WHERE id = $1
),
ins_org AS (
	INSERT INTO orgs (id, name, region, creation_ordinal)
	SELECT $2, $3, $4, CASE WHEN $8::bool THEN (SELECT org_creations FROM ledger) + 1 END
	FROM owned
	WHERE ($5::bigint IS NULL OR owned.n < $5)
	  AND (NOT $8::bool OR COALESCE((SELECT org_creation_limit IS NULL OR org_creations < org_creation_limit FROM ledger), true))
	RETURNING created_at
),
ins_membership AS (
	INSERT INTO memberships (id, account_id, org_id, role, zed_token, zed_token_at, activated_at)
	SELECT $6, $1, $2, 'owner', NULLIF($7, ''), CASE WHEN $7 <> '' THEN now() END, now()
	FROM ins_org
	RETURNING 1
),
bump AS (
	UPDATE accounts SET
		memberships_version = memberships_version + 1,
		org_creations = org_creations + CASE WHEN $8::bool THEN 1 ELSE 0 END
	WHERE id = $1 AND EXISTS (SELECT 1 FROM ins_org)
	RETURNING 1
)
SELECT (SELECT created_at FROM ins_org), (SELECT n FROM owned),
       (SELECT org_creations FROM ledger), (SELECT org_creation_limit FROM ledger)`

func (s *Store) createOrg(ctx context.Context, name, region string, ownerAccountID model.AccountID, enforceQuota bool) (OrgCreation, error) {
	org := &model.Org{
		ID:     model.NewOrgID(),
		Name:   name,
		Region: region,
	}

	var limit *int64
	if enforceQuota {
		l, err := s.orgQuotaLimit(ctx, ownerAccountID)
		if err != nil {
			return OrgCreation{}, fmt.Errorf("resolve organization quota: %w", err)
		}
		lim := int64(l)
		limit = &lim
	}

	rev, err := s.authz.OrgCreated(ctx, org.ID, ownerAccountID)
	if err != nil {
		wrapped := fmt.Errorf("authz org created: %w", err)
		s.rollbackOrgCreationAuthz(ctx, org.ID, wrapped)
		return OrgCreation{}, wrapped
	}

	ownerMembershipID := model.NewMembershipID()

	var (
		manageAllowed bool
		checkErr      error
		createdAt     *time.Time
		ownedCount    int64
		created       *int64
		creationLimit *int64
		sqlErr        error
		wg            sync.WaitGroup
	)
	wg.Add(2)
	go func() {
		defer wg.Done()
		manageAllowed, checkErr = s.authz.CanAtLeastAsFresh(ctx, rev, "account:"+ownerAccountID.String(), "manage", "org:"+org.ID.String())
	}()
	go func() {
		defer wg.Done()
		sqlErr = s.pool.QueryRow(ctx, createOrgSQL,
			ownerAccountID, org.ID, org.Name, org.Region, limit, ownerMembershipID, rev.Token(), enforceQuota,
		).Scan(&createdAt, &ownedCount, &created, &creationLimit)
	}()
	wg.Wait()

	if sqlErr != nil {
		// Only a ':' name can collide.
		if isUniqueViolation(sqlErr) {
			wrapped := fmt.Errorf("org name %q: %w", org.Name, ErrNameConflict)
			s.rollbackOrgCreationAuthz(ctx, org.ID, wrapped)
			return OrgCreation{}, wrapped
		}
		wrapped := fmt.Errorf("create org: %w", sqlErr)
		existingCreatedAt, exists, existsErr := s.orgRow(ctx, org.ID)
		switch resolveAmbiguousCommit(exists, existsErr) {
		case commitAmbiguitySucceeded:
			org.CreatedAt = existingCreatedAt
			if checkErr != nil {
				return OrgCreation{Org: org, Revision: rev}, s.logUnresolvableCapabilityCheck(ctx, org.ID, checkErr)
			}
			return OrgCreation{Org: org, Revision: rev, ManageAllowed: manageAllowed}, nil
		case commitAmbiguityFailed:
			s.rollbackOrgCreationAuthz(ctx, org.ID, wrapped)
		case commitAmbiguityUnresolved:
			slogutil.Error(ctx, "create org failure could not be resolved - SpiceDB tuples left in place",
				slog.String("org_id", org.ID.String()),
				slog.Any("check_err", existsErr),
				slog.Any("cause", wrapped))
		}
		return OrgCreation{}, wrapped
	}

	if createdAt == nil {
		wrapped := fmt.Errorf("account %s owns %d organizations: %w", ownerAccountID, ownedCount, ErrOrgQuotaExceeded)
		if enforceQuota && created != nil && creationLimit != nil && *created >= *creationLimit {
			wrapped = fmt.Errorf("account %s created %d of %d organizations: %w", ownerAccountID, *created, *creationLimit, ErrOrgCreationLimit)
		}
		s.rollbackOrgCreationAuthz(ctx, org.ID, wrapped)
		return OrgCreation{}, wrapped
	}
	org.CreatedAt = *createdAt
	if enforceQuota && created != nil {
		org.CreationOrdinal = *created + 1
	}

	if checkErr != nil {
		return OrgCreation{Org: org, Revision: rev}, s.logUnresolvableCapabilityCheck(ctx, org.ID, checkErr)
	}

	return OrgCreation{Org: org, Revision: rev, ManageAllowed: manageAllowed}, nil
}

func (s *Store) logUnresolvableCapabilityCheck(ctx context.Context, orgID model.OrgID, checkErr error) error {
	wrapped := fmt.Errorf("resolve owner capabilities: %w", checkErr)
	slogutil.Error(ctx, "capability check failed after org creation committed - org and its SpiceDB grants stand",
		slog.String("org_id", orgID.String()),
		slog.Any("cause", wrapped))
	return wrapped
}

func (s *Store) orgRow(ctx context.Context, id model.OrgID) (createdAt time.Time, exists bool, err error) {
	checkCtx, cancel := context.WithTimeout(context.WithoutCancel(ctx), 5*time.Second)
	defer cancel()
	err = s.pool.QueryRow(checkCtx, `SELECT created_at FROM orgs WHERE id = $1`, id).Scan(&createdAt)
	if errors.Is(err, pgx.ErrNoRows) {
		return time.Time{}, false, nil
	}
	if err != nil {
		return time.Time{}, false, fmt.Errorf("check org existence: %w", err)
	}
	return createdAt, true, nil
}

// rollbackOrgCreationAuthz undoes OrgCreated's SpiceDB write when a step
// after it fails and the org row will never exist. Best-effort: a failure
// here is logged, not returned — cause is what the caller reports.
func (s *Store) rollbackOrgCreationAuthz(ctx context.Context, id model.OrgID, cause error) {
	err := retryAuthzRollback(ctx, func(ctx context.Context) error {
		return s.authz.OrgCreationRolledBack(ctx, id)
	})
	if err != nil {
		slogutil.Error(ctx, "rollback after org create failure left SpiceDB tuples orphaned",
			slog.String("org_id", id.String()),
			slog.Any("rollback_err", err),
			slog.Any("cause", cause))
	}
}

func (s *Store) rollbackOrgCreate(ctx context.Context, id model.OrgID, cause error) {
	if err := s.deleteOrgRowAfterCreateFailure(ctx, id); err != nil {
		slogutil.Error(ctx, "rollback after org create failure - org row is orphaned",
			slog.String("org_id", id.String()),
			slog.Any("delete_err", err),
			slog.Any("cause", cause))
	}
}

