func (s *Store) AddMember(ctx context.Context, orgID model.OrgID, accountID model.AccountID, role string) (*model.Membership, error) {
	return s.addMember(ctx, orgID, accountID, role, model.MembershipStatusActive, "")
}

// AddWorkOSMember persists WorkOS status and the id used by group membership events.
func (s *Store) AddWorkOSMember(ctx context.Context, orgID model.OrgID, accountID model.AccountID, role, status, workosOrgMembershipID string) (*model.Membership, error) {
	return s.addMember(ctx, orgID, accountID, role, status, workosOrgMembershipID)
}

const addMemberSQL = `WITH ins AS (
	INSERT INTO memberships (id, account_id, org_id, role, status, workos_org_membership_id, activated_at)
	VALUES ($1, $2, $3, $4, $5, $6, CASE WHEN $5 = 'active' THEN now() END)
	RETURNING created_at
),
bump AS (
	UPDATE accounts SET memberships_version = memberships_version + 1
	WHERE id = $2 AND EXISTS (SELECT 1 FROM ins)
	RETURNING 1
)
SELECT created_at FROM ins`

func (s *Store) addMember(ctx context.Context, orgID model.OrgID, accountID model.AccountID, role, status, workosOrgMembershipID string) (*model.Membership, error) {
	var membership *model.Membership
	err := postgres.RetryOnSerializationFailure(ctx, func(ctx context.Context) error {
		var err error
		membership, err = s.addMemberOnce(ctx, orgID, accountID, role, status, workosOrgMembershipID)
		return err
	})
	if err != nil {
		return nil, fmt.Errorf("add member: %w", err)
	}
	return membership, nil
}

func (s *Store) addMemberOnce(ctx context.Context, orgID model.OrgID, accountID model.AccountID, role, status, workosOrgMembershipID string) (*model.Membership, error) {
	if err := validateMembershipStatus(status); err != nil {
		return nil, err
	}
	if role == "owner" {
		if status != model.MembershipStatusActive {
			return nil, fmt.Errorf("owner status %q: %w", status, ErrInvalidMembershipStatus)
		}
		return s.addOwnerMember(ctx, orgID, accountID, role, workosOrgMembershipID)
	}

	m := &model.Membership{
		ID:                    model.NewMembershipID(),
		AccountID:             accountID,
		OrgID:                 orgID,
		Role:                  role,
		Status:                status,
		WorkOSOrgMembershipID: workosOrgMembershipID,
	}
	var workosID *string
	if workosOrgMembershipID != "" {
		workosID = &workosOrgMembershipID
	}

	tx, err := s.pool.Begin(ctx)
	if err != nil {
		return nil, fmt.Errorf("begin membership insert: %w", err)
	}
	defer tx.Rollback(ctx) //nolint:errcheck // safe after commit

	// Claim the unique (account_id, org_id) row before touching authorization.
	// A duplicate must not re-grant access while a status update is suspending it.
	if err := tx.QueryRow(ctx, addMemberSQL,
		m.ID, accountID, orgID, role, status, workosID,
	).Scan(&m.CreatedAt); err != nil {
		if isMembershipDuplicate(err) {
			return nil, fmt.Errorf("account %s in org %s: %w", accountID, orgID, ErrAlreadyMember)
		}
		return nil, fmt.Errorf("insert membership: %w", err)
	}

	return s.finishMemberInsert(ctx, tx, m)
}

// finishMemberInsert grants/revokes and stamps authorization before making the
// inserted row visible. Competing inserts fail without touching its grants.
func (s *Store) finishMemberInsert(ctx context.Context, tx pgx.Tx, m *model.Membership) (*model.Membership, error) {
	rev, err := s.syncMembershipAuthorization(ctx, m.AccountID, m.OrgID, m.Role, m.Status)
	if err != nil {
		return nil, err
	}
	if _, err := tx.Exec(ctx,
		`UPDATE memberships SET zed_token = REDACTED, ''), zed_token_at = CASE WHEN $2 <> '' THEN now() END WHERE id = $1`,
		m.ID, rev.Token(),
	); err != nil {
		wrapped := fmt.Errorf("stamp membership: %w", err)
		if m.Status == model.MembershipStatusActive {
			s.rollbackMembershipGrant(ctx, m.AccountID, m.OrgID, wrapped)
		}
		return nil, wrapped
	}
	if err := tx.Commit(ctx); err != nil {
		return s.memberInsertCommitFailed(ctx, m, err)
	}
	return m, nil
}

// SetWorkOSMembershipStatus persists a lifecycle transition only when the
// event's WorkOS membership id matches the current local row.
func (s *Store) SetWorkOSMembershipStatus(ctx context.Context, orgID model.OrgID, accountID model.AccountID, workosOrgMembershipID, status string) error {
	if workosOrgMembershipID == "" {
		return errors.New("workos_org_membership_id required")
	}
	if err := validateMembershipStatus(status); err != nil {
		return err
	}

	if err := postgres.RetryOnSerializationFailure(ctx, func(ctx context.Context) error {
		return s.setWorkOSMembershipStatusOnce(ctx, orgID, accountID, workosOrgMembershipID, status)
	}); err != nil {
		return fmt.Errorf("set WorkOS membership status: %w", err)
	}
	return nil
}

func (s *Store) setWorkOSMembershipStatusOnce(ctx context.Context, orgID model.OrgID, accountID model.AccountID, workosOrgMembershipID, status string) error {
	tx, err := s.pool.Begin(ctx)
	if err != nil {
		return fmt.Errorf("begin membership status update: %w", err)
	}
	defer tx.Rollback(ctx) //nolint:errcheck // safe after commit

	// Claim the matching row before touching SpiceDB. The UPDATE serializes
	// competing writers and returns the role protected by this transaction.
	var membershipID model.MembershipID
	var role string
	err = tx.QueryRow(ctx,
		`WITH upd AS (
			UPDATE memberships
			SET status = $4,
			    activated_at = CASE WHEN $4 = 'active' AND status <> 'active' THEN now() ELSE activated_at END,
			    workos_org_membership_id = COALESCE(workos_org_membership_id, $3)
			WHERE org_id = $1 AND account_id = $2
			  AND (workos_org_membership_id IS NULL OR workos_org_membership_id = $3)
			RETURNING id, role
		),
		bump AS (
			UPDATE accounts SET memberships_version = memberships_version + 1
			WHERE id = $2 AND EXISTS (SELECT 1 FROM upd)
			RETURNING 1
		)
		SELECT id, role FROM upd`,
		orgID, accountID, workosOrgMembershipID, status,
	).Scan(&membershipID, &role)
	if errors.Is(err, pgx.ErrNoRows) {
		return fmt.Errorf("membership for account %s in org %s with WorkOS id %q: %w", accountID, orgID, workosOrgMembershipID, ErrNotFound)
	}
	if err != nil {
		return fmt.Errorf("update WorkOS membership status: %w", err)
	}

	rev, err := s.syncMembershipAuthorization(ctx, accountID, orgID, role, status)
	if err != nil {
		return err
	}
	if _, err = tx.Exec(ctx,
		`UPDATE memberships SET zed_token = REDACTED, ''), zed_token_at = CASE WHEN $2 <> '' THEN now() END WHERE id = $1`,
		membershipID, rev.Token(),
	); err == nil {
		err = tx.Commit(ctx)
	}
	if err != nil {
		wrapped := fmt.Errorf("persist membership authorization: %w", err)
		// A failed activation stays revoked, even if COMMIT's outcome is
		// uncertain. Retrying the event reconciles status and authorization.
		if status == model.MembershipStatusActive {
			s.rollbackMembershipGrant(ctx, accountID, orgID, wrapped)
		}
		return wrapped
	}
	return nil
}

func validateMembershipStatus(status string) error {
	switch status {
	case model.MembershipStatusActive, model.MembershipStatusInactive, model.MembershipStatusPending:
		return nil
	default:
		return fmt.Errorf("%q: %w", status, ErrInvalidMembershipStatus)
	}
}

func validateMembershipRole(role string) error {
	switch role {
	case "owner", "admin", "member":
		return nil
	default:
		return fmt.Errorf("%q: %w", role, ErrInvalidRole)
	}
}

// UpdateMemberRole changes a membership without replacing its identity,
// lifecycle status, WorkOS linkage, creation time, or team memberships. The
// returned string is the previous role for audit logging.
// An error does not guarantee rollback or agreement between the database and
// SpiceDB: recovery after a failed write is bounded and best-effort.
func (s *Store) UpdateMemberRole(ctx context.Context, orgID model.OrgID, membershipID model.MembershipID, role string) (*model.Membership, string, error) {
	return s.updateMemberRole(ctx, orgID, membershipID, role, nil)
}

func (s *Store) UpdateMemberRoleIfRole(ctx context.Context, orgID model.OrgID, membershipID model.MembershipID, expectedRole, role string) (*model.Membership, string, error) {
	return s.updateMemberRole(ctx, orgID, membershipID, role, &expectedRole)
}

func (s *Store) updateMemberRole(ctx context.Context, orgID model.OrgID, membershipID model.MembershipID, role string, expectedRole *string) (*model.Membership, string, error) {
	if err := validateMembershipRole(role); err != nil {
		return nil, "", err
