2199		}
2200		defer cleanupTx.Rollback(cleanupCtx) //nolint:errcheck // safe after commit
2201	
2202		m := &model.Membership{ID: membershipID, OrgID: orgID}
2203		err = cleanupTx.QueryRow(cleanupCtx,
2204			`SELECT account_id, role, status, COALESCE(workos_org_membership_id, ''), created_at
2205			 FROM memberships WHERE org_id = $1 AND id = $2 FOR UPDATE`,
2206			orgID, membershipID,
2207		).Scan(&m.AccountID, &m.Role, &m.Status, &m.WorkOSOrgMembershipID, &m.CreatedAt)
2208		if errors.Is(err, pgx.ErrNoRows) {
2209			return nil
2210		}
2211		if err != nil {
2212			slogutil.Error(ctx, "membership role reconciliation could not read committed role", slog.Any("error", err), slog.Any("cause", cause))
2213			return nil
2214		}
2215		rev, err := s.syncChangedMembershipAuthorization(cleanupCtx, m)
2216		if err != nil {
2217			slogutil.Error(ctx, "membership role reconciliation authorization failed", slog.Any("error", err), slog.Any("cause", cause))
2218			return nil
2219		}
2220		if _, err := cleanupTx.Exec(cleanupCtx,
2221			`UPDATE memberships SET zed_token = REDACTED, ''), zed_token_at = CASE WHEN $2 <> '' THEN now() END WHERE id = $1`,
2222			m.ID, rev.Token(),
2223		); err != nil {
2224			slogutil.Error(ctx, "membership role reconciliation stamp failed", slog.Any("error", err), slog.Any("cause", cause))
2225			return nil
2226		}
2227		if err := cleanupTx.Commit(cleanupCtx); err != nil {
2228			slogutil.Error(ctx, "membership role reconciliation commit failed", slog.Any("error", err), slog.Any("cause", cause))
2229			return nil
2230		}
2231		return m
2232	}
