func (s *Store) updateMemberRoleOnce(ctx context.Context, orgID model.OrgID, membershipID model.MembershipID, role string, expectedRole *string) (*model.Membership, string, error) {
	tx, err := s.pool.Begin(ctx)
	if err != nil {
		return nil, "", fmt.Errorf("begin membership role update: %w", err)
	}
	defer tx.Rollback(ctx) //nolint:errcheck // safe after commit or explicit rollback

	m := &model.Membership{ID: membershipID, OrgID: orgID}
	var orgName string
	// Lock the shared org row as well as the target membership. Serializing all
	// role changes for one org makes the active-owner count below stable even
	// when concurrent requests demote different owners.
	err = tx.QueryRow(ctx,
		`SELECT m.account_id, m.role, m.status, COALESCE(m.workos_org_membership_id, ''), m.created_at, o.name
		 FROM memberships m JOIN orgs o ON o.id = m.org_id
		 WHERE m.org_id = $1 AND m.id = $2
		 FOR UPDATE OF m, o`,
		orgID, membershipID,
	).Scan(&m.AccountID, &m.Role, &m.Status, &m.WorkOSOrgMembershipID, &m.CreatedAt, &orgName)
	if errors.Is(err, pgx.ErrNoRows) {
		return nil, "", fmt.Errorf("membership %s in org %s: %w", membershipID, orgID, ErrNotFound)
	}
	if err != nil {
		return nil, "", fmt.Errorf("lock membership: %w", err)
	}
	if expectedRole != nil && m.Role != *expectedRole {
		return nil, "", ErrMembershipRoleChanged
	}
	previousRole := m.Role
	if previousRole == role {
		rev, err := s.syncChangedMembershipAuthorization(ctx, m)
		if err != nil {
			s.rollbackAndReconcileMembershipRole(ctx, tx, m.ID, m.OrgID, err)
			return nil, "", err
		}
		if _, err := tx.Exec(ctx,
			`UPDATE memberships SET zed_token = REDACTED, ''), zed_token_at = CASE WHEN $2 <> '' THEN now() END WHERE id = $1`,
			m.ID, rev.Token(),
		); err != nil {
			wrapped := fmt.Errorf("stamp unchanged membership role authorization: %w", err)
			s.rollbackAndReconcileMembershipRole(ctx, tx, m.ID, m.OrgID, wrapped)
			return nil, "", wrapped
		}
		return s.finishMemberRoleUpdate(ctx, tx, m, previousRole)
	}
	if role == "owner" && m.Status != model.MembershipStatusActive {
		return nil, "", fmt.Errorf("owner status %q: %w", m.Status, ErrInvalidMembershipStatus)
	}
	if previousRole == "owner" && m.Status == model.MembershipStatusActive {
		var owners int
		if err := tx.QueryRow(ctx,
			`SELECT count(*) FROM memberships WHERE org_id = $1 AND role = 'owner' AND status = 'active'`,
			orgID,
		).Scan(&owners); err != nil {
			return nil, "", fmt.Errorf("count organization owners: %w", err)
		}
		if owners <= 1 {
			return nil, "", ErrLastOrgOwner
		}
	}
	if role == "owner" && !strings.ContainsRune(orgName, ':') {
		// The account row is the quota lock shared by owner promotions across
		// different organizations. Without it, two transactions could both
		// observe one remaining slot and claim it. Valid organization members
		// always have an account row; a missing row is corrupt membership data.
		var lockedAccountID model.AccountID
		if err := tx.QueryRow(ctx, `SELECT id FROM accounts WHERE id = $1 FOR UPDATE`, m.AccountID).Scan(&lockedAccountID); err != nil {
			return nil, "", fmt.Errorf("lock account for organization quota: %w", err)
		}
		quotaLimit, err := s.orgQuotaLimit(ctx, m.AccountID)
		if err != nil {
			return nil, "", fmt.Errorf("resolve organization quota: %w", err)
		}
		var owned int
		if err := tx.QueryRow(ctx,
			`SELECT count(*) FROM memberships m JOIN orgs o ON o.id = m.org_id
			 WHERE m.account_id = $1 AND m.role = 'owner' AND m.status = 'active'
			   AND strpos(o.name, ':') = 0`,
			m.AccountID,
		).Scan(&owned); err != nil {
			return nil, "", fmt.Errorf("count owned organizations: %w", err)
		}
		if owned >= quotaLimit {
			return nil, "", fmt.Errorf("account %s owns %d organizations: %w", m.AccountID, owned, ErrOrgQuotaExceeded)
		}
	}

	if _, err := tx.Exec(ctx, `UPDATE memberships SET role = $3 WHERE org_id = $1 AND id = $2`, orgID, membershipID, role); err != nil {
		return nil, "", fmt.Errorf("persist membership role: %w", err)
	}
	if err := bumpMembershipsVersion(ctx, tx, m.AccountID); err != nil {
		return nil, "", err
	}

	m.Role = role
	rev, err := s.syncChangedMembershipAuthorization(ctx, m)
	if err != nil {
		s.rollbackAndReconcileMembershipRole(ctx, tx, m.ID, m.OrgID, err)
		return nil, "", err
	}
	if _, err := tx.Exec(ctx,
		`UPDATE memberships SET zed_token = REDACTED, ''), zed_token_at = CASE WHEN $2 <> '' THEN now() END WHERE id = $1`,
		m.ID, rev.Token(),
	); err != nil {
		wrapped := fmt.Errorf("stamp membership role authorization: %w", err)
		s.rollbackAndReconcileMembershipRole(ctx, tx, m.ID, m.OrgID, wrapped)
		return nil, "", wrapped
	}
	return s.finishMemberRoleUpdate(ctx, tx, m, previousRole)
}

// finishMemberRoleUpdate resolves an ambiguous COMMIT by reconciling the
// membership role that is actually visible after the transaction releases its
// locks. It is separate from updateMemberRoleOnce so the ambiguity window can
// be tested deterministically.
func (s *Store) finishMemberRoleUpdate(ctx context.Context, tx pgx.Tx, m *model.Membership, previousRole string) (*model.Membership, string, error) {
	if err := tx.Commit(ctx); err != nil {
		wrapped := fmt.Errorf("commit membership role: %w", err)
		current := s.rollbackAndReconcileMembershipRole(ctx, tx, m.ID, m.OrgID, wrapped)
		if current != nil && current.Role == m.Role {
			return current, previousRole, nil
		}
		return nil, "", wrapped
	}
	return m, previousRole, nil
}

func (s *Store) syncChangedMembershipAuthorization(ctx context.Context, m *model.Membership) (authz.Revision, error) {
	if m.Status != model.MembershipStatusActive {
		rev, err := s.authz.MembershipRevoked(ctx, m.AccountID, m.OrgID)
		if err != nil {
			return authz.Revision{}, fmt.Errorf("authz membership revoked: %w", err)
		}
		return rev, nil
	}
	rev, err := s.authz.MembershipRoleChanged(ctx, m.AccountID, m.OrgID, m.Role)
	if err != nil {
		return authz.Revision{}, fmt.Errorf("authz membership role changed: %w", err)
	}
	return rev, nil
}

// rollbackAndReconcileMembershipRole releases the failed writer's row locks,
// then locks and reconciles whatever membership row actually committed. This
// handles both ordinary statement failures and an ambiguous COMMIT without
// restoring a stale role over a concurrent successful writer.
//
// Cleanup has a five-second budget independent of request cancellation. A
// timeout or unavailable dependency can leave stale SpiceDB permissions,
// including excess access. Callers retain the original error; cleanup failures
// are logged, and this path schedules no durable retry. A later successful
// UpdateMemberRole call reconciles authorization even when the role is unchanged.
func (s *Store) rollbackAndReconcileMembershipRole(ctx context.Context, tx pgx.Tx, membershipID model.MembershipID, orgID model.OrgID, cause error) *model.Membership {
	cleanupCtx, cancel := context.WithTimeout(context.WithoutCancel(ctx), 5*time.Second)
	defer cancel()
	if err := tx.Rollback(cleanupCtx); err != nil && !errors.Is(err, pgx.ErrTxClosed) {
		slogutil.Error(ctx, "membership role rollback failed", slog.Any("error", err), slog.Any("cause", cause))
	}

	cleanupTx, err := s.pool.Begin(cleanupCtx)
	if err != nil {
		slogutil.Error(ctx, "membership role reconciliation could not begin", slog.Any("error", err), slog.Any("cause", cause))
		return nil
	}
	defer cleanupTx.Rollback(cleanupCtx) //nolint:errcheck // safe after commit

	m := &model.Membership{ID: membershipID, OrgID: orgID}
	err = cleanupTx.QueryRow(cleanupCtx,
		`SELECT account_id, role, status, COALESCE(workos_org_membership_id, ''), created_at
		 FROM memberships WHERE org_id = $1 AND id = $2 FOR UPDATE`,
		orgID, membershipID,
	).Scan(&m.AccountID, &m.Role, &m.Status, &m.WorkOSOrgMembershipID, &m.CreatedAt)
	if errors.Is(err, pgx.ErrNoRows) {
		return nil
	}
	if err != nil {
		slogutil.Error(ctx, "membership role reconciliation could not read committed role", slog.Any("error", err), slog.Any("cause", cause))
		return nil
	}
	rev, err := s.syncChangedMembershipAuthorization(cleanupCtx, m)
	if err != nil {
		slogutil.Error(ctx, "membership role reconciliation authorization failed", slog.Any("error", err), slog.Any("cause", cause))
		return nil
	}
	if _, err := cleanupTx.Exec(cleanupCtx,
		`UPDATE memberships SET zed_token = REDACTED, ''), zed_token_at = CASE WHEN $2 <> '' THEN now() END WHERE id = $1`,
		m.ID, rev.Token(),
	); err != nil {
		slogutil.Error(ctx, "membership role reconciliation stamp failed", slog.Any("error", err), slog.Any("cause", cause))
		return nil
	}
	if err := cleanupTx.Commit(cleanupCtx); err != nil {
		slogutil.Error(ctx, "membership role reconciliation commit failed", slog.Any("error", err), slog.Any("cause", cause))
		return nil
	}
	return m
}

func (s *Store) syncMembershipAuthorization(ctx context.Context, accountID model.AccountID, orgID model.OrgID, role, status string) (authz.Revision, error) {
	if status == model.MembershipStatusActive {
		rev, err := s.authz.MembershipGranted(ctx, accountID, orgID, role)
		if err != nil {
			return authz.Revision{}, fmt.Errorf("authz membership granted: %w", err)
		}
		return rev, nil
	}
	rev, err := s.authz.MembershipRevoked(ctx, accountID, orgID)
	if err != nil {
		return authz.Revision{}, fmt.Errorf("authz membership revoked: %w", err)
	}
	return rev, nil
}

// memberInsertCommitFailed reconciles authorization after an ambiguous commit.
func (s *Store) memberInsertCommitFailed(ctx context.Context, m *model.Membership, err error) (*model.Membership, error) {
	wrapped := fmt.Errorf("commit membership: %w", err)
	existingCreatedAt, exists, existsErr := s.membershipRow(ctx, m.ID)
	switch resolveAmbiguousCommit(exists, existsErr) {
	case commitAmbiguitySucceeded:
		m.CreatedAt = existingCreatedAt
		return m, nil
	case commitAmbiguityFailed:
		if m.Status == model.MembershipStatusActive {
			s.rollbackMembershipGrant(ctx, m.AccountID, m.OrgID, wrapped)
		}
	case commitAmbiguityUnresolved:
		slogutil.Error(ctx, "insert membership failure could not be resolved - SpiceDB tuples left in place",
			slog.String("membership_id", m.ID.String()),
			slog.Any("check_err", existsErr),
			slog.Any("cause", wrapped))
	}
	return nil, wrapped
}

// addOwnerMemberSQL claims the membership before authorization, like addMemberSQL.
// $5 is the quota limit. Existing memberships still produce a duplicate error
// rather than a quota rejection.
const addOwnerMemberSQL = `WITH org AS (
	SELECT name FROM orgs WHERE id = $3
),
owned AS (
	SELECT count(*) AS n
	FROM memberships m JOIN orgs o ON o.id = m.org_id
	WHERE m.account_id = $2 AND m.role = 'owner' AND m.status = 'active'
	  AND strpos(o.name, ':') = 0
),
ins AS (
	INSERT INTO memberships (id, account_id, org_id, role, workos_org_membership_id, activated_at)
	SELECT $1, $2, $3, 'owner', $4, now()
	FROM org, owned
	WHERE strpos(org.name, ':') > 0 OR owned.n < $5
	   OR EXISTS (SELECT 1 FROM memberships WHERE account_id = $2 AND org_id = $3)
	RETURNING created_at
),
bump AS (
	UPDATE accounts SET memberships_version = memberships_version + 1
	WHERE id = $2 AND EXISTS (SELECT 1 FROM ins)
	RETURNING 1
)
SELECT (SELECT created_at FROM ins), (SELECT n FROM owned), EXISTS(SELECT 1 FROM org)`

func (s *Store) addOwnerMember(ctx context.Context, orgID model.OrgID, accountID model.AccountID, role, workosOrgMembershipID string) (*model.Membership, error) {
	m := &model.Membership{
		ID:                    model.NewMembershipID(),
		AccountID:             accountID,
		OrgID:                 orgID,
		Role:                  role,
		Status:                "active",
		WorkOSOrgMembershipID: workosOrgMembershipID,
	}
	var workosID *string
	if workosOrgMembershipID != "" {
		workosID = &workosOrgMembershipID
	}

	limit, err := s.orgQuotaLimit(ctx, accountID)
	if err != nil {
		return nil, fmt.Errorf("resolve organization quota: %w", err)
	}

	tx, err := s.pool.Begin(ctx)
	if err != nil {
		return nil, fmt.Errorf("begin owner membership insert: %w", err)
	}
	defer tx.Rollback(ctx) //nolint:errcheck // safe after commit

	var (
		createdAt  *time.Time
		ownedCount int64
		orgExists  bool
	)
	err = tx.QueryRow(ctx, addOwnerMemberSQL,
		m.ID, accountID, orgID, workosID, int64(limit),
	).Scan(&createdAt, &ownedCount, &orgExists)
	if err != nil {
		if isMembershipDuplicate(err) {
			return nil, fmt.Errorf("account %s in org %s: %w", accountID, orgID, ErrAlreadyMember)
		}
		return nil, fmt.Errorf("insert owner membership: %w", err)
	}

	if !orgExists {
		return nil, fmt.Errorf("org %s: %w", orgID, ErrNotFound)
	}
	if createdAt == nil {
		return nil, fmt.Errorf("account %s owns %d organizations: %w", accountID, ownedCount, ErrOrgQuotaExceeded)
	}
	m.CreatedAt = *createdAt

	return s.finishMemberInsert(ctx, tx, m)
}

// commitAmbiguity classifies a failed write by rechecking whether its row exists.
type commitAmbiguity int

const (
	commitAmbiguitySucceeded commitAmbiguity = iota
	commitAmbiguityFailed
	// Preserve grants when the commit outcome cannot be verified.
	commitAmbiguityUnresolved
)

func resolveAmbiguousCommit(exists bool, checkErr error) commitAmbiguity {
	switch {
	case checkErr == nil && exists:
		return commitAmbiguitySucceeded
	case checkErr == nil && !exists:
		return commitAmbiguityFailed
	default:
		return commitAmbiguityUnresolved
	}
}

func (s *Store) membershipRow(ctx context.Context, id model.MembershipID) (createdAt time.Time, exists bool, err error) {
	checkCtx, cancel := context.WithTimeout(context.WithoutCancel(ctx), 5*time.Second)
	defer cancel()
	err = s.pool.QueryRow(checkCtx, `SELECT created_at FROM memberships WHERE id = $1`, id).Scan(&createdAt)
	if errors.Is(err, pgx.ErrNoRows) {
		return time.Time{}, false, nil
	}
	if err != nil {
		return time.Time{}, false, fmt.Errorf("check membership existence: %w", err)
	}
	return createdAt, true, nil
}

// rollbackMembershipGrant revokes a speculative grant, logging cleanup failures.
func (s *Store) rollbackMembershipGrant(ctx context.Context, accountID model.AccountID, orgID model.OrgID, cause error) {
	cleanupCtx, cancel := context.WithTimeout(context.WithoutCancel(ctx), 5*time.Second)
	defer cancel()
	if _, err := s.authz.MembershipRevoked(cleanupCtx, accountID, orgID); err != nil {
		slogutil.Error(ctx, "rollback after addMember failure left SpiceDB tuples orphaned",
			slog.String("account_id", accountID.String()),
			slog.String("org_id", orgID.String()),
			slog.Any("rollback_err", err),
			slog.Any("cause", cause))
	}
}

// RemoveMember revokes source-managed/internal memberships even when the
// target is the last owner. An upstream deletion must not leave access behind.
