}

func (s *Store) removeMember(ctx context.Context, orgID model.OrgID, accountID model.AccountID, expectedRole *string, expectedID *model.MembershipID) error {
	if err := postgres.RetryOnSerializationFailure(ctx, func(ctx context.Context) error {
		return s.removeMemberOnce(ctx, orgID, accountID, expectedRole, expectedID)
	}); err != nil {
		return fmt.Errorf("remove member: %w", err)
	}

	// The membership row is already gone, so MembershipRevoked's Revision has
	// nothing left to stamp.
	if _, err := s.authz.MembershipRevoked(ctx, accountID, orgID); err != nil {
		return fmt.Errorf("authz membership revoked: %w", err)
	}
	return nil
}

func (s *Store) removeMemberOnce(ctx context.Context, orgID model.OrgID, accountID model.AccountID, expectedRole *string, expectedID *model.MembershipID) error {
	tx, err := s.pool.Begin(ctx)
	if err != nil {
		return fmt.Errorf("begin membership removal: %w", err)
	}
	defer tx.Rollback(ctx) //nolint:errcheck // safe after commit

	var membershipID model.MembershipID
	var role, status string
	if err := tx.QueryRow(ctx,
		`SELECT m.id, m.role, m.status
		 FROM memberships m JOIN orgs o ON o.id = m.org_id
		 WHERE m.org_id = $1 AND m.account_id = $2
		 FOR UPDATE OF m, o`,
		orgID, accountID,
	).Scan(&membershipID, &role, &status); err != nil {
		if errors.Is(err, pgx.ErrNoRows) {
			return fmt.Errorf("membership for account %s in org %s: %w", accountID, orgID, ErrNotFound)
		}
		return fmt.Errorf("lock membership for removal: %w", err)
	}
	if expectedID != nil && membershipID != *expectedID {
		return ErrNotFound
	}
	if expectedRole != nil && role != *expectedRole {
		return ErrMembershipRoleChanged
	}
	if expectedRole != nil && role == "owner" && status == model.MembershipStatusActive {
		var owners int
		if err := tx.QueryRow(ctx,
			`SELECT count(*) FROM memberships WHERE org_id = $1 AND role = 'owner' AND status = 'active'`,
			orgID,
		).Scan(&owners); err != nil {
			return fmt.Errorf("count organization owners: %w", err)
		}
		if owners <= 1 {
			return ErrLastOrgOwner
		}
	}
	if _, err := tx.Exec(ctx, `DELETE FROM memberships WHERE org_id = $1 AND account_id = $2`, orgID, accountID); err != nil {
		return fmt.Errorf("delete membership: %w", err)
	}
	if err := bumpMembershipsVersion(ctx, tx, accountID); err != nil {
		return err
	}
	if err := tx.Commit(ctx); err != nil {
		return fmt.Errorf("commit membership removal: %w", err)
	}
	return nil
}

