// DeleteTeam removes the team and all team memberships in a single DB
// transaction, then clears SpiceDB relations for the team. Best-effort
// authz cleanup: if the SpiceDB call fails, the DB is the source of
// truth and the team row is gone.
func (s *Store) DeleteTeam(ctx context.Context, teamID model.TeamID) error {
	tx, err := s.pool.Begin(ctx)
	if err != nil {
		return fmt.Errorf("begin tx: %w", err)
	}
	defer tx.Rollback(ctx) //nolint:errcheck // safe if commit succeeded

	if _, err := tx.Exec(ctx,
		`DELETE FROM team_memberships WHERE team_id = $1`, teamID,
	); err != nil {
		return fmt.Errorf("delete team memberships: %w", err)
	}

	tag, err := tx.Exec(ctx, `DELETE FROM teams WHERE id = $1`, teamID)
	if err != nil {
		return fmt.Errorf("delete team: %w", err)
	}
	if tag.RowsAffected() == 0 {
		return fmt.Errorf("team %s: %w", teamID, ErrNotFound)
	}

	if err := tx.Commit(ctx); err != nil {
		return fmt.Errorf("commit tx: %w", err)
	}

	if err := s.authz.TeamDeleted(ctx, teamID); err != nil {
		slogutil.Error(ctx, "authz team deleted cleanup failed (DB delete committed)",
			slog.String("team_id", teamID.String()),
			slog.String("error", err.Error()),
		)
	}
	return nil
}

func (s *Store) AddTeamMember(ctx context.Context, teamID model.TeamID, membershipID model.MembershipID) error {
	_, err := s.pool.Exec(ctx,
		`INSERT INTO team_memberships (membership_id, team_id) VALUES ($1, $2)`,
		membershipID, teamID,
	)
	if err != nil {
		return fmt.Errorf("insert team membership: %w", err)
	}

	// Resolve membership to account ID for the authz relation.
	var accountID model.AccountID
	err = s.pool.QueryRow(ctx, `SELECT account_id FROM memberships WHERE id = $1`, membershipID).Scan(&accountID)
	if err != nil {
		return fmt.Errorf("resolve membership: %w", err)
	}

	if err := s.authz.TeamMemberAdded(ctx, accountID, teamID); err != nil {
		return fmt.Errorf("authz team member added: %w", err)
	}

	return nil
}

func (s *Store) RemoveTeamMember(ctx context.Context, teamID model.TeamID, membershipID model.MembershipID) error {
	// Resolve membership to account ID before deleting the team membership
	// row, so we can clean the authz tuple afterwards.
	var accountID model.AccountID
	err := s.pool.QueryRow(ctx, `SELECT account_id FROM memberships WHERE id = $1`, membershipID).Scan(&accountID)
	if err != nil {
		if errors.Is(err, pgx.ErrNoRows) {
			return fmt.Errorf("membership %s: %w", membershipID, ErrNotFound)
		}
		return fmt.Errorf("resolve membership: %w", err)
	}

	tag, err := s.pool.Exec(ctx,
		`DELETE FROM team_memberships WHERE team_id = $1 AND membership_id = $2`,
		teamID, membershipID,
	)
	if err != nil {
		return fmt.Errorf("delete team membership: %w", err)
	}
	if tag.RowsAffected() == 0 {
		return fmt.Errorf("team membership: %w", ErrNotFound)
	}

	if err := s.authz.TeamMemberRemoved(ctx, accountID, teamID); err != nil {
		return fmt.Errorf("authz team member removed: %w", err)
	}
	return nil
}

