// --- Projects ---

// createProjectOrgSQL and createProjectAccountSQL are single implicit
// transactions, like createOrgSQL. $5 is the quota limit, and only
// entire-forge projects count toward it. The org variant's strpos check
// exempts ':'-namespaced system orgs from quota, and it returns owner-row
// existence to tell a quota rejection apart from a vanished org.
//
// $7 says the name is in the reserved list. It gates two things that must
// happen together: the project INSERT needs a live grant, and that grant is
// marked consumed. use_grant joins ins_project, so a create the quota or the
// unique name index rejects leaves the grant open for the next attempt.
// use_grant's RETURNING is not decoration - CockroachDB rejects a WITH clause
// that returns no columns.
const createProjectOrgSQL = `WITH owner_org AS (
	SELECT name FROM orgs WHERE id = $1
),
owned AS (
	SELECT count(*) AS n FROM projects
	WHERE owner_type = 'org' AND owner_id = $1 AND forge = 'entire'
),
live_grant AS (
	SELECT id FROM reserved_name_grants
	WHERE $7::BOOL AND scope = 'project' AND name = $3
	  AND owner_type = 'org' AND owner_id = $1
	  AND consumed_at IS NULL AND revoked_at IS NULL AND expires_at > now()
),
ins_project AS (
	INSERT INTO projects (id, name, owner_type, owner_id, region, forge, primary_processing_cell)
	-- NULLIF: "" means unassigned, which the migration stores as NULL.
	SELECT $2, $3, 'org', $1, $4, 'entire', NULLIF($6, '')
	FROM owner_org, owned
	WHERE (strpos(owner_org.name, ':') > 0 OR owned.n < $5)
	  AND (NOT $7::BOOL OR EXISTS (SELECT 1 FROM live_grant))
	RETURNING id, created_at
),
use_grant AS (
	UPDATE reserved_name_grants g
	SET consumed_at = now(), consumed_resource_id = p.id
	FROM ins_project p
	WHERE g.id = (SELECT id FROM live_grant)
	RETURNING g.id
)
SELECT (SELECT created_at FROM ins_project), (SELECT n FROM owned),
       EXISTS(SELECT 1 FROM owner_org), EXISTS(SELECT 1 FROM live_grant)`

const createProjectAccountSQL = `WITH owned AS (
	SELECT count(*) AS n FROM projects
	WHERE owner_type = 'account' AND owner_id = $1 AND forge = 'entire'
),
live_grant AS (
	SELECT id FROM reserved_name_grants
	WHERE $7::BOOL AND scope = 'project' AND name = $3
	  AND owner_type = 'account' AND owner_id = $1
	  AND consumed_at IS NULL AND revoked_at IS NULL AND expires_at > now()
),
ins_project AS (
	INSERT INTO projects (id, name, owner_type, owner_id, region, forge, primary_processing_cell)
	-- NULLIF: "" means unassigned, which the migration stores as NULL.
	SELECT $2, $3, 'account', $1, $4, 'entire', NULLIF($6, '')
	FROM owned
	WHERE owned.n < $5
	  AND (NOT $7::BOOL OR EXISTS (SELECT 1 FROM live_grant))
	RETURNING id, created_at
),
use_grant AS (
	UPDATE reserved_name_grants g
	SET consumed_at = now(), consumed_resource_id = p.id
	FROM ins_project p
	WHERE g.id = (SELECT id FROM live_grant)
	RETURNING g.id
)
SELECT (SELECT created_at FROM ins_project), (SELECT n FROM owned),
       EXISTS(SELECT 1 FROM live_grant)`

// hasLiveReservedNameGrant reports whether an unconsumed, unrevoked, unexpired
// grant lets this owner create this reserved name. CreateProject asks before it
// writes SpiceDB tuples, so the common refusal costs one read and no rollback.
// The create statement re-checks and consumes the same grant atomically, so a
// grant taken between the two reads still fails the create.
func (s *Store) hasLiveReservedNameGrant(ctx context.Context, name, ownerType string, ownerID model.ID) (bool, error) {
	var found bool
	err := s.pool.QueryRow(ctx,
		`SELECT EXISTS (
			SELECT 1 FROM reserved_name_grants
			WHERE scope = 'project' AND name = $1
			  AND owner_type = $2 AND owner_id = $3
			  AND consumed_at IS NULL AND revoked_at IS NULL AND expires_at > now()
		)`, name, ownerType, ownerID,
	).Scan(&found)
	if err != nil {
		return false, fmt.Errorf("look up reserved name grant: %w", err)
	}
	return found, nil
}

func (s *Store) CreateProject(ctx context.Context, name, ownerType string, ownerID model.ID, region, cell string) (ProjectCreation, error) {
	return s.createProject(ctx, name, ownerType, ownerID, region, cell, false)
}

// CreateGitHubOwnerProject skips the reserved-name gate.
func (s *Store) CreateGitHubOwnerProject(ctx context.Context, name string, accountID model.AccountID, region, cell string) (ProjectCreation, error) {
	return s.createProject(ctx, name, "account", model.ID(accountID.String()), region, cell, true)
}

func (s *Store) createProject(ctx context.Context, name, ownerType string, ownerID model.ID, region, cell string, githubOwner bool) (ProjectCreation, error) {
	name, err := normalizeProjectName(name)
	if err != nil {
		return ProjectCreation{}, err
	}
	reserved := !githubOwner && isReservedProjectName(name)
	if reserved {
		granted, err := s.hasLiveReservedNameGrant(ctx, name, ownerType, ownerID)
		if err != nil {
			return ProjectCreation{}, err
		}
		if !granted {
			return ProjectCreation{}, fmt.Errorf("project name %q: %w", name, ErrReservedName)
		}
		if s.afterReservedNameGrantCheckForTest != nil {
			s.afterReservedNameGrantCheckForTest(ctx)
		}
	}

	p := &model.Project{
		ID:                    model.NewProjectID(),
		Name:                  name,
		Forge:                 model.ProjectForgeEntire,
		OwnerType:             ownerType,
		OwnerID:               ownerID,
		Region:                region,
		PrimaryProcessingCell: cell,
	}

	limit, err := s.projectQuotaLimit(ctx, ownerType, ownerID)
	if err != nil {
		return ProjectCreation{}, fmt.Errorf("resolve project quota: %w", err)
	}

	rev, err := s.authz.ProjectCreated(ctx, p.ID, ownerType, ownerID)
	if err != nil {
		wrapped := fmt.Errorf("authz project created: %w", err)
		s.rollbackProjectCreationAuthz(ctx, p.ID, wrapped)
		return ProjectCreation{}, wrapped
	}

	var (
		createdAt   *time.Time
		ownedCount  int64
		ownerExists bool
		grantLive   bool
		sqlErr      error
	)
	switch ownerType {
	case "org":
		sqlErr = s.pool.QueryRow(ctx, createProjectOrgSQL,
			ownerID, p.ID, p.Name, p.Region, int64(limit), p.PrimaryProcessingCell, reserved,
		).Scan(&createdAt, &ownedCount, &ownerExists, &grantLive)
	case "account":
		ownerExists = true
		sqlErr = s.pool.QueryRow(ctx, createProjectAccountSQL,
			ownerID, p.ID, p.Name, p.Region, int64(limit), p.PrimaryProcessingCell, reserved,
		).Scan(&createdAt, &ownedCount, &grantLive)
	default:
		wrapped := fmt.Errorf("project owner type %q: %w", ownerType, ErrInvalidName)
		s.rollbackProjectCreationAuthz(ctx, p.ID, wrapped)
		return ProjectCreation{}, wrapped
	}

	if sqlErr != nil {
		if isUniqueViolation(sqlErr) {
			wrapped := fmt.Errorf("project name %q: %w", p.Name, ErrNameConflict)
			s.rollbackProjectCreationAuthz(ctx, p.ID, wrapped)
			return ProjectCreation{}, wrapped
		}
		wrapped := fmt.Errorf("create project: %w", sqlErr)
		existingCreatedAt, exists, existsErr := s.projectRow(ctx, p.ID)
		switch resolveAmbiguousCommit(exists, existsErr) {
		case commitAmbiguitySucceeded:
			p.CreatedAt = existingCreatedAt
			return ProjectCreation{Project: p, Revision: rev}, nil
		case commitAmbiguityFailed:
			s.rollbackProjectCreationAuthz(ctx, p.ID, wrapped)
		case commitAmbiguityUnresolved:
			slogutil.Error(ctx, "create project failure could not be resolved - SpiceDB tuples left in place",
				slog.String("project_id", p.ID.String()),
				slog.Any("check_err", existsErr),
				slog.Any("cause", wrapped))
		}
		return ProjectCreation{}, wrapped
	}

	if !ownerExists {
		wrapped := fmt.Errorf("project %q: %w", p.Name, ErrOwnerGone)
		s.rollbackProjectCreationAuthz(ctx, p.ID, wrapped)
		return ProjectCreation{}, wrapped
	}
	if createdAt == nil {
		// A concurrent create took the grant between the pre-check and this
		// statement. The name is still reserved against this caller.
		if reserved && !grantLive {
			wrapped := fmt.Errorf("project name %q: %w", p.Name, ErrReservedName)
			s.rollbackProjectCreationAuthz(ctx, p.ID, wrapped)
			return ProjectCreation{}, wrapped
		}
		wrapped := fmt.Errorf("%s owner %s owns %d projects: %w", ownerType, ownerID, ownedCount, ErrProjectQuotaExceeded)
		s.rollbackProjectCreationAuthz(ctx, p.ID, wrapped)
		return ProjectCreation{}, wrapped
	}
	p.CreatedAt = *createdAt

	return ProjectCreation{Project: p, Revision: rev}, nil
}

func (s *Store) projectRow(ctx context.Context, id model.ProjectID) (createdAt time.Time, exists bool, err error) {
	checkCtx, cancel := context.WithTimeout(context.WithoutCancel(ctx), 5*time.Second)
	defer cancel()
	err = s.pool.QueryRow(checkCtx, `SELECT created_at FROM projects WHERE id = $1`, id).Scan(&createdAt)
	if errors.Is(err, pgx.ErrNoRows) {
		return time.Time{}, false, nil
	}
	if err != nil {
		return time.Time{}, false, fmt.Errorf("check project existence: %w", err)
	}
	return createdAt, true, nil
}

// rollbackProjectCreationAuthz undoes ProjectCreated's SpiceDB write when a
// later step fails and the project row will never exist. Best-effort: a
// failure here is logged, not returned — cause is what the caller reports.
func (s *Store) rollbackProjectCreationAuthz(ctx context.Context, id model.ProjectID, cause error) {
	err := retryAuthzRollback(ctx, func(ctx context.Context) error {
		if _, err := s.authz.ProjectDeleted(ctx, id); err != nil {
			return fmt.Errorf("project deleted: %w", err)
		}
		return nil
	})
	if err != nil {
		slogutil.Error(ctx, "rollback after project create failure left SpiceDB tuples orphaned",
			slog.String("project_id", id.String()),
			slog.Any("rollback_err", err),
			slog.Any("cause", cause))
	}
}

// authzRollbackBudget bounds one create rollback. SpiceDB writes queue on a
// shared overlap row under bursts (COR-473), so a single write can wait
// several seconds before it commits.
const authzRollbackBudget = 15 * time.Second

// retryAuthzRollback runs fn until it succeeds or the budget ends. The
// request context may already be canceled, so the budget is independent of
// it. Only a saturated SpiceDB write path is retried; a down SpiceDB
// returns at once so a failed create does not hold its request.
//
// This is the only retry on this path: the rollbacks call DeleteRelationships
// directly, and authz's writeWithRetry covers WriteRelationships alone. The
// rollback runs before the create's error reaches the caller, so a saturated
// SpiceDB can hold a failed create for the whole budget. An orphaned owner
// tuple costs more than that wait.
func retryAuthzRollback(ctx context.Context, fn func(context.Context) error) error {
	cleanupCtx, cancel := context.WithTimeout(context.WithoutCancel(ctx), authzRollbackBudget)
	defer cancel()
	backoff := 50 * time.Millisecond
	for {
		err := fn(cleanupCtx)
		if err == nil || !authz.IsSaturatedWrite(err) {
			return err
		}
		select {
		case <-cleanupCtx.Done():
			return err
		case <-time.After(backoff):
		}
		backoff = min(backoff*2, 2*time.Second)
	}
}

