// Before this, an org name was arbitrary text bounded only by length and a
// ban on ':'. That made it the one name a self-serve caller could fill with
// markup or control characters, and org names reach consumers that do not
// escape.
func normalizeOrgName(name string) (string, error) {
	trimmed := strings.TrimSpace(name)
	if isReservedOrgName(trimmed) {
		return "", fmt.Errorf("org name %q is reserved: %w", trimmed, ErrReservedName)
	}
	return normalizeName("org name", trimmed, orgNameMinLen, orgNameMaxLen, false)
}

