func (s *Store) deleteProject(ctx context.Context, id model.ProjectID, keepInstalledMirrors bool) (ProjectDeletion, error) {
	// Retry on SQLSTATE 40001, same posture (and reason) as DeleteOrg: under
	// serializable isolation any concurrent transaction touching an
	// overlapping row — e.g. a parallel PublishRepo writing repo_registry
	// and its indexes near our count read — can abort this one with a
	// retryable error, and the whole body must re-run from begin to commit.
	//
