	// attempt opens a *fresh* uncertainty window, so under sustained
	// contention the retries chase newly-pushed writes instead of converging.
	// That is why 5 -> 8 (#3015) did not stop TestDeleteProject_Empty_OK
	// flaking. The single-node dev/CI cluster narrows the window with
	// --max-offset instead; production is CockroachDB Cloud, where max_offset
	// is not tunable, so the budget stays for genuine write contention.
	const maxAttempts = 8
	backoff := 5 * time.Millisecond
