	for attempt := range maxAttempts {
		deleted, err := s.deleteProjectTx(ctx, id, keepInstalledMirrors)
		if err == nil {
			return deleted, nil
		}
		lastErr = err
		if !isSerializationFailure(err) || attempt == maxAttempts-1 {
			return ProjectDeletion{}, err
		}
		// Same warn as DeleteOrg: without it an exhausted budget and a
		// first-attempt failure are indistinguishable in the logs, which is
		// what made run 31136516733 unfalsifiable after the fact.
		slogutil.Warn(ctx, "DeleteProject retrying on serialization failure",
			slog.String("project_id", id.String()),
			slog.Int("attempt", attempt+1),
			slog.Any("error", err))
