package coreapi

import (
	"context"
	"log/slog"
	"slices"

	"entire.io/api/corev1"
	"entire.io/core/api"
	"entire.io/core/cluster"
	"entire.io/slogutil"
)

func (s *ProjectService) setProjectListRouting(ctx context.Context, projects []corev1.Project) {
	refs := make([]*corev1.Project, len(projects))
	for i := range projects {
		refs[i] = &projects[i]
	}
	s.setProjectRouting(ctx, refs...)
}

// setProjectRouting reads the catalog once per response, not once per project.
// Catalog failures withhold URLs without hiding project metadata or assignments.
func (s *ProjectService) setProjectRouting(ctx context.Context, projects ...*corev1.Project) {
	if !slices.ContainsFunc(projects, func(p *corev1.Project) bool { return p.PrimaryProcessingCell != "" }) {
		return
	}
	clusters, err := s.regions().ActiveClusters(ctx)
	if err != nil {
		slogutil.Warn(ctx, "project API routing unavailable", slog.Any("error", err))
		return
	}
	// Hidden clusters still serve assigned projects. ActiveClusters excludes
	// decommissioned clusters; neither a default nor a Git replica can replace them.
	available := make(map[[2]string]api.ClusterInfo, len(clusters))
	for _, c := range clusters {
		if c.Cell != "" && c.Jurisdiction != "" {
			available[[2]string{c.Cell, c.Jurisdiction}] = c
		}
	}
	for _, p := range projects {
		c, ok := available[[2]string{p.PrimaryProcessingCell, p.Region}]
		if !ok {
			continue
		}
		hosts, err := cluster.DerivePublicHosts(c.Cell, c.PublicURL, s.APIHostOverrides)
		if err != nil {
			slogutil.Warn(ctx, "project API routing unavailable", slog.String("cell", c.Cell), slog.Any("error", err))
			continue
		}
		p.APIURL = hosts.APIBaseURL
	}
}
