func (s *ProjectService) CreateProject(ctx context.Context, in *corev1.CreateProjectInput) (*corev1.CreateProjectOutput, error) {
	claims := api.ClaimsFromContext(ctx)
	if claims == nil {
		return nil, unauthorized("authentication required")
	}
	res := s.Server.Resource()
	authz := s.Server.Authz()
	idSvc := s.Server.Identity()
	if res == nil || authz == nil || idSvc == nil {
		return nil, unavailable("services not configured")
	}
	region := in.Body.Region
	if region == "" {
		region = s.Server.Jurisdiction()
	} else if err := s.validateKnownRegion(ctx, region); err != nil {
		return nil, err
	}
	ownerID, err := model.ParseID(in.Body.OwnerID)
	if err != nil {
		return nil, badRequest("invalid ownerId")
	}

	var loadedOrg *model.Org // set on the org-owner path, to name the response's owner without a second lookup
	switch in.Body.OwnerType {
	case "org":
		orgID, err := model.ParseOrgID(in.Body.OwnerID)
		if err != nil {
			return nil, badRequest("invalid ownerId")
		}
		org, err := res.GetOrg(ctx, orgID)
		if err != nil {
			if errors.Is(err, resource.ErrNotFound) {
				return nil, notFound("org not found")
			}
			slogutil.Error(ctx, "GetOrg failed", slog.Any("error", err))
			return nil, internalErr()
		}
		allowed, err := s.ManageAuthority.gateAllowed(ctx, coreauthz.RetryDeniedFresh, authz, "account:"+claims.AccountID.String(), "manage", "org:"+orgID.String())
		if err != nil {
			slogutil.Error(ctx, "authz.Can failed", slog.Any("error", err))
			return nil, authzUnavailable()
		}
		if !allowed {
			return nil, forbidden("permission denied")
		}
		if ok, reason := s.Server.CheckOrgSSOForOrg(claims, org); !ok {
			return nil, forbidden(reason)
		}
		loadedOrg = org
	case "account":
		acctID, err := model.ParseAccountID(in.Body.OwnerID)
		if err != nil {
			return nil, badRequest("invalid ownerId")
		}
		if _, err := idSvc.GetAccount(ctx, acctID); err != nil {
			if errors.Is(err, identity.ErrNotFound) {
				return nil, notFound("account not found")
			}
			slogutil.Error(ctx, "GetAccount failed", slog.Any("error", err))
			return nil, internalErr()
		}
		if claims.AccountID.String() != ownerID.String() {
			if !s.ManageAuthority.allowsWrite(ctx) {
				return nil, forbidden("permission denied")
			}
		}
	default:
		return nil, badRequest("invalid ownerType: must be org or account")
	}

	// Resolve the project's processing home ONCE, here, and persist it with the
	// row (ADR 20260909-project-primary-processing-cell). A jurisdiction can
	// serve several cells, so the region alone cannot name a home, and deriving
	// one per request would let a topology change relocate existing projects.
	//
	// Gated: writing assignments is only safe once every node enforces them.
	// While the gate is closed the project is stored unassigned, exactly as
	// every project predating the column is, and placement keeps taking the
	// pre-assignment path. A jurisdiction with no usable default is a 503 —
	// better to refuse the create than to mint a project with no home.
	var cell string
	if s.Server.ProjectCellAssignmentEnabled() {
		resolved, cellErr := s.Server.DefaultProcessingCell(ctx, region)
		if cellErr != nil {
			slogutil.Error(ctx, "CreateProject: resolve processing cell failed",
				slog.String("region", region), slog.Any("error", cellErr))
			return nil, unavailable(fmt.Sprintf("no processing cell available for region %q", region))
		}
		cell = resolved
	}

	created, err := res.CreateProject(ctx, in.Body.Name, in.Body.OwnerType, ownerID, region, cell)
	// Never for orgs: anyone can name one.
	githubOwner := errors.Is(err, resource.ErrReservedName) &&
		in.Body.OwnerType == "account" && claims.AccountID.String() == ownerID.String()
	if githubOwner {
		created, err = s.createAsGitHubOwner(ctx, claims.AccountID, in.Body.Name, region, cell)
	}
	if err != nil {
		return nil, mapCreateProjectError(ctx, err, in.Body.Name)
	}
	project := created.Project
	// The reference shape for a write-then-read handler here (CreateOrg is the
	// other): the capability read is pinned to the create's own SpiceDB write
	// via its Revision, so it observes the owner relations just written instead
	// of whatever the region-local replica has caught up to. Without that, a
	// project's creator could be told they cannot manage the project they just
	// made.
	caps, err := projectCapabilitiesAtLeastAsFresh(ctx, s.Server, s.ManageAuthority, created.Revision, claims.AccountID.String(), project)
	if err != nil {
		// The project and its SpiceDB owner grants are real at this point;
		// only the read of them failed. Leave both in place rather than
		// deleting a project whose grants are correct.
		slogutil.Error(ctx, "CreateProject: capability check failed after create committed",
			slog.String("project_id", project.ID.String()), slog.Any("error", err))
		return nil, internalErr()
	}
	meta := map[string]any{
		"name":       project.Name,
		"owner_type": in.Body.OwnerType,
		"owner_id":   in.Body.OwnerID,
	}
	if githubOwner {
		meta["reserved_name_source"] = "github_owner"
	}
	s.Server.DomainAuditLog(ctx, claims.AccountID, "project_created", "project", project.ID.String(), meta)
	s.Server.LifecycleEvents().Publish(ctx, resourceevents.TypeProject, project.ID.String(), resourceevents.OpCreated, claims.AccountID.String())
	var ownerName string
	if loadedOrg != nil {
		ownerName = loadedOrg.Name
	} else {
		ownerName = resolveOwnerName(ctx, s.Server, project)
	}
	wire := projectToWire(project, ownerName)
	s.setProjectRouting(ctx, &wire)
	wire.Capabilities = caps
	token := s.mintCreateProjectToken(ctx, project.ID, created.Revision)
	return &corev1.CreateProjectOutput{Status: http.StatusCreated, CommitToken: token, Body: corev1.CreatedProject{
		Project:     wire,
		CommitToken: token,
	}}, nil
}

// The GitHub owner may claim reserved names.
func (s *ProjectService) createAsGitHubOwner(ctx context.Context, account model.AccountID, name, region, cell string) (resource.ProjectCreation, error) {
	handles, err := s.Server.Identity().ListHandles(ctx, account)
	if err != nil {
		return resource.ProjectCreation{}, fmt.Errorf("list handles: %w", err)
	}
	if !ownsGitHubLogin(handles, strings.TrimSpace(name)) {
		return resource.ProjectCreation{}, fmt.Errorf("project name %q: %w", name, resource.ErrReservedName)
	}
	created, err := s.Server.Resource().CreateGitHubOwnerProject(ctx, name, account, region, cell)
	if err != nil {
		return resource.ProjectCreation{}, fmt.Errorf("create as GitHub owner: %w", err)
	}
	return created, nil
}

// mintCreateProjectToken signs both halves of the write the caller is about to
// list. A failed timestamp read still mints the revision half, which is what
// names the project in the listing at all.
func (s *ProjectService) mintCreateProjectToken(ctx context.Context, projectID model.ProjectID, rev coreauthz.Revision) string {
	if !s.Server.CommitTokens().Enabled() {
		return ""
	}
	token, err := s.Server.Resource().ProjectCommitToken(ctx, projectID)
	if err != nil {
		slogutil.Warn(ctx, "create project: read commit timestamp failed",
			slog.String("project_id", projectID.String()), slog.Any("error", err))
	}
	return signCommitToken(ctx, s.Server, "create_project",
		committoken.Snapshot{Commit: token, Revision: rev.Token()})
}

// validateKnownRegion rejects a caller-specified region no cluster has ever
// named, so an explicit Project.Region always identifies a jurisdiction.
// The accept-set is every jurisdiction in AllClusters (hidden and
// decommissioned included, plus this core's own unconditionally, so an
// unwired registry can't 400 a caller naming home) — an org homed in a
// since-decommissioned jurisdiction must still be able to create projects
// there. The error text on a miss names only visible, active jurisdictions:
// what a caller could plausibly pick going forward.
func (s *ProjectService) validateKnownRegion(ctx context.Context, region string) error {
	if region == s.Server.Jurisdiction() {
		return nil
	}
	all, err := s.regions().AllClusters(ctx)
	if err != nil {
		slogutil.Error(ctx, "AllClusters failed", slog.Any("error", err))
		return internalErr()
	}
	known := make(map[string]bool, len(all))
	for _, c := range all {
		known[c.Jurisdiction] = true
	}
	if known[region] {
		return nil
	}

	active, err := s.regions().ActiveClusters(ctx)
	if err != nil {
		slogutil.Error(ctx, "ActiveClusters failed", slog.Any("error", err))
		return internalErr()
	}
	visible := make(map[string]bool, len(active))
	for _, c := range active {
		if !c.Hidden {
			visible[c.Jurisdiction] = true
		}
	}
	valid := slices.Sorted(maps.Keys(visible))
	if len(valid) == 0 {
		return badRequest(fmt.Sprintf("unknown region %q; no jurisdictions are registered", region))
	}
	return badRequest(fmt.Sprintf("unknown region %q; valid jurisdictions: %s", region, strings.Join(valid, ", ")))
}

// mapCreateProjectError turns a resource.CreateProject failure into the
// response a client sees. It is a function, not an inline switch, so the
// problem types can be pinned by a test without a database — the same shape
// mapCreateNativeRepoError already has. name appears in the reserved-name
// prose, so it is the caller's raw input.
func mapCreateProjectError(ctx context.Context, err error, name string) error {
	switch {
	case errors.Is(err, resource.ErrInvalidName):
		return withType(problemTypeProjectNameInvalid, badRequest("invalid project name"))
	case errors.Is(err, resource.ErrReservedName):
		return withType(problemTypeProjectNameReserved, conflict(fmt.Sprintf("project name %q is reserved — it matches a well-known public account; please contact support@entire.io if it's really you :)", strings.TrimSpace(name))))
	case errors.Is(err, resource.ErrNameConflict):
		return withType(problemTypeProjectNameInUse, conflict("project name already in use"))
	case errors.Is(err, resource.ErrProjectQuotaExceeded):
		return withType(problemTypeProjectQuotaReached, conflict("project limit reached"))
	default:
		slogutil.Error(ctx, "CreateProject failed", slog.Any("error", err))
		return internalErr()
	}
}

