// validateKnownRegion rejects a caller-specified region no cluster has ever
// named, so an explicit Project.Region always identifies a jurisdiction.
// The accept-set is every jurisdiction in AllClusters (hidden and
// decommissioned included, plus this core's own unconditionally, so an
// unwired registry can't 400 a caller naming home) — an org homed in a
// since-decommissioned jurisdiction must still be able to create projects
// there. The error text on a miss names only visible, active jurisdictions:
// what a caller could plausibly pick going forward.
func (s *ProjectService) validateKnownRegion(ctx context.Context, region string) error {
	if region == s.Server.Jurisdiction() {
		return nil
	}
	all, err := s.regions().AllClusters(ctx)
	if err != nil {
		slogutil.Error(ctx, "AllClusters failed", slog.Any("error", err))
		return internalErr()
	}
	known := make(map[string]bool, len(all))
	for _, c := range all {
		known[c.Jurisdiction] = true
	}
	if known[region] {
		return nil
	}

	active, err := s.regions().ActiveClusters(ctx)
	if err != nil {
		slogutil.Error(ctx, "ActiveClusters failed", slog.Any("error", err))
		return internalErr()
	}
	visible := make(map[string]bool, len(active))
	for _, c := range active {
		if !c.Hidden {
			visible[c.Jurisdiction] = true
		}
	}
	valid := slices.Sorted(maps.Keys(visible))
	if len(valid) == 0 {
		return badRequest(fmt.Sprintf("unknown region %q; no jurisdictions are registered", region))
	}
	return badRequest(fmt.Sprintf("unknown region %q; valid jurisdictions: %s", region, strings.Join(valid, ", ")))
}

// mapCreateProjectError turns a resource.CreateProject failure into the
// response a client sees. It is a function, not an inline switch, so the
// problem types can be pinned by a test without a database — the same shape
// mapCreateNativeRepoError already has. name appears in the reserved-name
// prose, so it is the caller's raw input.
func mapCreateProjectError(ctx context.Context, err error, name string) error {
	switch {
	case errors.Is(err, resource.ErrInvalidName):
		return withType(problemTypeProjectNameInvalid, badRequest("invalid project name"))
	case errors.Is(err, resource.ErrReservedName):
		return withType(problemTypeProjectNameReserved, conflict(fmt.Sprintf("project name %q is reserved — it matches a well-known public account; please contact support@entire.io if it's really you :)", strings.TrimSpace(name))))
	case errors.Is(err, resource.ErrNameConflict):
		return withType(problemTypeProjectNameInUse, conflict("project name already in use"))
	case errors.Is(err, resource.ErrProjectQuotaExceeded):
		return withType(problemTypeProjectQuotaReached, conflict("project limit reached"))
	default:
		slogutil.Error(ctx, "CreateProject failed", slog.Any("error", err))
		return internalErr()
	}
}

