func (s *OrgService) CreateOrg(ctx context.Context, in *corev1.CreateOrgInput) (*corev1.CreateOrgOutput, error) {
	claims := api.ClaimsFromContext(ctx)
	if claims == nil {
		return nil, unauthorized("authentication required")
	}
	res := s.Server.Resource()
	if res == nil {
		return nil, unavailable("resource service not configured")
	}
	region := in.Body.Region
	if region == "" {
		region = s.Server.Jurisdiction()
	}
	created, err := res.CreateOrg(ctx, in.Body.Name, region, claims.AccountID)
	if err != nil {
		switch {
		case errors.Is(err, resource.ErrInvalidName):
			return nil, badRequest("invalid org name")
		case errors.Is(err, resource.ErrReservedName):
			return nil, badRequest("org name is reserved")
		case errors.Is(err, resource.ErrOrgQuotaExceeded):
			return nil, conflict("organization limit reached")
		case errors.Is(err, resource.ErrOrgCreationLimit):
			return nil, conflict("organization creation limit reached")
		case created.Org != nil:
			// The org exists and its owner grant stands - only the
			// post-commit capability freshness check failed. Report it as
			// created rather than a false failure; ManageAllowed is
			// already false since the check never resolved.
			slogutil.Error(ctx, "CreateOrg succeeded but capability check failed",
				slog.Any("error", err), slog.String("org_id", created.Org.ID.String()))
		default:
			slogutil.Error(ctx, "CreateOrg failed", slog.Any("error", err))
			return nil, internalErr()
		}
	}
	org := created.Org
	s.Server.DomainAuditLog(ctx, claims.AccountID, "org_created", "org", org.ID.String(), map[string]any{"name": in.Body.Name})
	s.Server.LifecycleEvents().Publish(ctx, resourceevents.TypeOrg, org.ID.String(), resourceevents.OpCreated, claims.AccountID.String())

	wire := orgToWire(org)
	wire.Capabilities = corev1.OrgCapabilities{CanCreateProject: created.ManageAllowed, CanManageMembers: created.ManageAllowed, CanDelete: created.ManageAllowed, CanManageBilling: created.ManageAllowed, CanView: created.ManageAllowed, CanListProjects: created.ManageAllowed}
	if authz := s.Server.Authz(); created.ManageAllowed && authz != nil {
		// Pin the owner check to the creation write too. Management alone is
		// not proof of ownership, even if this caller originally created it.
		ownerAllowed, err := authz.CanAtLeastAsFresh(ctx, created.Revision, "account:"+claims.AccountID.String(), "owner", "org:"+org.ID.String())
		if err != nil {
			// Creation has committed: disclose no owner capability, but do not
			// report a failed create that would invite a duplicate retry.
			slogutil.Error(ctx, "CreateOrg succeeded but owner capability check failed",
				slog.Any("error", err), slog.String("org_id", org.ID.String()))
		} else {
			wire.Capabilities.CanChangeOwners = ownerAllowed
		}
	}
	token := s.mintOrgListToken(ctx, "create_org", claims.AccountID)
	return &corev1.CreateOrgOutput{Status: http.StatusCreated, CommitToken: token, Body: corev1.CreatedOrg{
		Org:         wire,
		CommitToken: token,
	}}, nil
}

