// the write that just landed. Pass the accounts the write bumped: the creator
// for a create, every member for a delete.
//
// Commit half only, unlike the project token: the membership row the snapshot
// reveals carries the ZedToken the capability check needs.
func (s *OrgService) AddOrgMember(ctx context.Context, in *corev1.AddOrgMemberInput) (*corev1.AddOrgMemberOutput, error) {
	claims := api.ClaimsFromContext(ctx)
	if claims == nil {
		return nil, unauthorized("authentication required")
	}
	orgID, err := model.ParseOrgID(in.OrgID)
	if err != nil {
		return nil, badRequest("invalid org id")
	}
	res := s.Server.Resource()
	idSvc := s.Server.Identity()
	if res == nil || idSvc == nil {
		return nil, unavailable("resource service not configured")
	}
	if _, err := res.GetOrg(ctx, orgID); err != nil {
		if errors.Is(err, resource.ErrNotFound) {
			return nil, notFound("org not found")
		}
		slogutil.Error(ctx, "GetOrg failed", slog.Any("error", err))
		return nil, internalErr()
	}
	if allowed, err := s.ManageAuthority.checkOrgManage(ctx, s.Server, claims, orgID); err != nil {
		slogutil.Error(ctx, "CheckOrgManage failed", slog.Any("error", err))
		return nil, authzUnavailable()
	} else if !allowed {
		return nil, forbidden("permission denied")
	}
	if ok, reason, err := s.Server.CheckOrgSSO(ctx, claims, orgID); err != nil {
		slogutil.Error(ctx, "CheckOrgSSO failed", slog.Any("error", err))
		return nil, authzUnavailable()
	} else if !ok {
		return nil, forbidden(reason)
	}
	if linked, err := res.IsGitHubLinkedOrg(ctx, orgID); err != nil {
		slogutil.Error(ctx, "mirror guard: org link lookup failed", slog.String("org_id", orgID.String()), slog.String("op", "add_org_member"), slog.Any("error", err))
		return nil, internalErr()
	} else if linked {
		return nil, conflict(api.MirrorOrgMemberRejectedMsg)
	}
	role := in.Body.Role
	if role == "" {
		role = "member"
	}
	if role == "owner" {
		if err := s.requireOrgOwner(ctx, claims, orgID, ownerRoleGateMsg); err != nil {
			return nil, err
		}
	}
	acct, handle, err := idSvc.ResolveHandleByProviderID(ctx, model.HandleProvider(in.Body.Provider), in.Body.ProviderUserID)
	if err != nil {
		return nil, notFound("provider identity not found")
	}
	membership, err := res.AddMember(ctx, orgID, acct.ID, role)
	if err != nil {
		if errors.Is(err, resource.ErrNotFound) {
			return nil, notFound("org not found")
		}
		if errors.Is(err, resource.ErrOrgQuotaExceeded) {
			return nil, conflict("organization limit reached")
		}
		if errors.Is(err, resource.ErrAlreadyMember) {
			return nil, conflict("account is already a member of this organization")
		}
		slogutil.Error(ctx, "AddMember failed", slog.Any("error", err))
		return nil, internalErr()
	}
	s.Server.DomainAuditLog(ctx, claims.AccountID, "member_added", "org", orgID.String(), map[string]any{
		"provider":         in.Body.Provider,
		"provider_user_id": in.Body.ProviderUserID,
		"role":             role,
	})
	s.Server.LifecycleEvents().Publish(ctx, resourceevents.TypeOrgMember, orgID.String(), resourceevents.OpCreated, claims.AccountID.String())
	username := usernamesByAccount(ctx, idSvc, []string{acct.ID.String()})[acct.ID.String()]
	// ListOrgMembers may show a different, primary handle.
	return &corev1.AddOrgMemberOutput{Status: http.StatusCreated, Body: membershipToWire(membership, formatHandle(handle), string(handle.Provider), username)}, nil
}

