	// runs zero-scope OAuth, and forwards to the user's home region's
	// /api/authz/debug-bounce after the round-trip.
	s.mux.HandleFunc("GET /api/authz/debug-bounce", s.handleGlobalDebugBounce)
	// Jurisdiction handoff: lets a trusted RP (the entire.io BFF) discover a
	// user's home jurisdiction via zero-scope GitHub OAuth.
	s.mux.HandleFunc("GET /api/auth/resolve-jurisdiction", s.handleGlobalResolveJurisdiction)
