	// forward the CLI's OAuth entry points to the jurisdiction whose regional
	// core actually runs the login, so the CLI can hardcode one login host.
	// See core/api/global_oidc_dispatch.go.
	s.mux.HandleFunc("GET /authorize", s.handleGlobalAuthorize)
